CATALOG.add([
  // ── Grammar blocks 1-7 ──
  { id: 's:own:n4-te-adj-noun-heya', kind: 'sentence', level: 'N4', jp: 'このへやはしずかで、明るいです。', reading: 'このへやはしずかで、あかるいです。', en: 'This room is quiet and bright.', uses: ['g:te-adj-noun', 'k:明', 'v:明るい|あかるい', 'v:この|この', 'v:部屋|へや', 'v:静か|しずか'], furigana: 'このへやはしずかで、[明|あか]るいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10901873', kind: 'sentence', level: 'N4', jp: 'この花は赤くて、きれいです。', reading: 'このはなはあかくて、きれいです。', en: 'These flowers are red and beautiful.', uses: ['g:te-adj-noun', 'k:花', 'k:赤', 'v:赤い|あかい', 'v:きれい|きれい', 'v:この|この', 'v:花|はな'], furigana: 'この[花|はな]は[赤|あか]くて、きれいです。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12010561, enAuthor: 'Winter', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-adj-noun-hon', kind: 'sentence', level: 'N4', jp: 'この本はかんたんで、おもしろいです。', reading: 'このほんはかんたんで、おもしろいです。', en: 'This book is easy and interesting.', uses: ['g:te-adj-noun', 'k:本', 'v:この|この', 'v:本|ほん', 'v:簡単|かんたん', 'v:おもしろい|おもしろい'], furigana: 'この[本|ほん]はかんたんで、おもしろいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-adj-noun-ramen', kind: 'sentence', level: 'N4', jp: 'この店のラーメンは安くて、おいしいです。', reading: 'このみせのラーメンはやすくて、おいしいです。', en: 'The ramen at this shop is cheap and tasty.', uses: ['g:te-adj-noun', 'k:店', 'k:安', 'v:おいしい|おいしい', 'v:この|この', 'v:店|みせ', 'v:安い|やすい'], furigana: 'この[店|みせ]のラーメンは[安|やす]くて、おいしいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:190695', kind: 'sentence', level: 'N4', jp: '一つは新しくて、もう一つは古いものです。', reading: 'ひとつはあたらしくて、もうひとつはふるいものです。', en: 'One is new, and the other is old.', uses: ['g:te-adj-noun', 'k:一', 'k:新', 'k:古', 'v:新しい|あたらしい', 'v:一つ|ひとつ', 'v:古い|ふるい', 'v:もう|もう'], furigana: '[一|ひと]つは[新|あたら]しくて、もう[一|ひと]つは[古|ふる]いものです。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 27855, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10901517', kind: 'sentence', level: 'N4', jp: '病気で学校を休みました。', reading: 'びょうきでがっこうをやすみました。', en: 'I was sick, so I didn\'t go to school.', uses: ['g:te-adj-noun', 'k:病', 'k:気', 'k:学', 'k:校', 'k:休', 'v:学校|がっこう', 'v:病気|びょうき', 'v:休む|やすむ'], furigana: '[病気|びょう|き]で[学校|がっ|こう]を[休|やす]みました。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 4664037, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nakute-imi', kind: 'sentence', level: 'N4', jp: 'ことばの意味がわからなくて、こまりました。', reading: 'ことばのいみがわからなくて、こまりました。', en: 'I didn\'t understand what the word meant, so I was stuck.', uses: ['g:nakute', 'k:意', 'k:味', 'v:意味|いみ', 'v:言葉|ことば', 'v:分かる|わかる', 'v:困る|こまる'], furigana: 'ことばの[意味|いみ]がわからなくて、こまりました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11527067', kind: 'sentence', level: 'N4', jp: 'いいえ。ドイツ人じゃなくて、トルコ人です。', reading: 'いいえ。ドイツじんじゃなくて、トルコじんです。', en: 'No, I\'m not a German, I\'m a Turk.', uses: ['g:nakute', 'k:人', 'v:いいえ|いいえ', 'v:人|じん'], furigana: 'いいえ。ドイツ[人|じん]じゃなくて、トルコ[人|じん]です。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 8343181, enAuthor: 'AlanF_US', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10140581', kind: 'sentence', level: 'N4', jp: 'これはあなたの本じゃなくて、私のよ。', reading: 'これはあなたのほんじゃなくて、わたしのよ。', en: 'This isn\'t your book. It\'s mine.', uses: ['g:nakute', 'k:本', 'k:私', 'v:あなた|あなた', 'v:これ|これ', 'v:本|ほん', 'v:私|わたし'], furigana: 'これはあなたの[本|ほん]じゃなくて、[私|わたし]のよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10140569, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:172932', kind: 'sentence', level: 'N4', jp: '今、ちょっとお金が足りなくてね。', reading: 'いま、ちょっとおかねがたりなくてね。', en: 'I\'m a bit short of money now.', uses: ['g:nakute', 'k:今', 'k:金', 'k:足', 'v:今|いま', 'v:お金|おかね', 'v:ちょっと|ちょっと', 'v:足りる|たりる'], furigana: '[今|いま]、ちょっとお[金|かね]が[足|た]りなくてね。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 241541, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-noun-modifier-hon', kind: 'sentence', level: 'N4', jp: 'きのう買った本はおもしろいです。', reading: 'きのうかったほんはおもしろいです。', en: 'The book I bought yesterday is interesting.', uses: ['g:noun-modifier', 'g:ta-form', 'k:買', 'k:本', 'v:おもしろい|おもしろい', 'v:買う|かう', 'v:本|ほん', 'v:昨日|きのう'], furigana: 'きのう[買|か]った[本|ほん]はおもしろいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11831566', kind: 'sentence', level: 'N4', jp: 'トムの買った車は赤だよ。', reading: 'トムのかったくるまはあかだよ。', en: 'The car Tom bought is red.', uses: ['g:noun-modifier', 'g:ta-form', 'k:買', 'k:車', 'k:赤', 'v:赤|あか', 'v:買う|かう', 'v:車|くるま'], furigana: 'トムの[買|か]った[車|くるま]は[赤|あか]だよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 6349939, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1107908', kind: 'sentence', level: 'N4', jp: 'この間父が書いた本を見つけた。', reading: 'このあいだちちがかいたほんをみつけた。', en: 'The other day, I found a book written by my father.', uses: ['g:noun-modifier', 'g:ta-form', 'k:間', 'k:父', 'k:書', 'k:本', 'k:見', 'v:書く|かく', 'v:本|ほん', 'v:見つける|みつける', 'v:この間|このあいだ'], furigana: 'この[間|あいだ][父|ちち]が[書|か]いた[本|ほん]を[見|み]つけた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 12579120, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-noun-modifier-megane', kind: 'sentence', level: 'N4', jp: 'めがねをかけている人はわたしの兄です。', reading: 'めがねをかけているひとはわたしのあにです。', en: 'The person wearing glasses is my older brother.', uses: ['g:noun-modifier', 'g:te-iru', 'g:te-form', 'k:人', 'k:兄', 'v:兄|あに', 'v:かける|かける', 'v:人|ひと', 'v:眼鏡|めがね', 'v:私|わたし'], furigana: 'めがねをかけている[人|ひと]はわたしの[兄|あに]です。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11720950', kind: 'sentence', level: 'N4', jp: '外で待ってる人がいるよ。', reading: 'そとでまってるひとがいるよ。', en: 'There\'s someone waiting outside.', uses: ['g:noun-modifier', 'g:te-form', 'k:外', 'k:待', 'k:人', 'v:外|そと', 'v:人|ひと', 'v:待つ|まつ'], furigana: '[外|そと]で[待|ま]ってる[人|ひと]がいるよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 11811287, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:152797', kind: 'sentence', level: 'N4', jp: '私は本を読んでいました。', reading: 'わたしはほんをよんでいました。', en: 'I was reading a book.', uses: ['g:te-ita', 'g:te-form', 'k:私', 'k:本', 'k:読', 'v:本|ほん', 'v:読む|よむ', 'v:私|わたし'], furigana: '[私|わたし]は[本|ほん]を[読|よ]んでいました。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 261751, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:225305', kind: 'sentence', level: 'N4', jp: 'ケーキを作っていました。', reading: 'ケーキをつくっていました。', en: 'I was making a cake.', uses: ['g:te-ita', 'g:te-form', 'k:作', 'v:作る|つくる', 'v:ケーキ|ケーキ'], furigana: 'ケーキを[作|つく]っていました。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 62642, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:12515162', kind: 'sentence', level: 'N4', jp: 'トムはコートを着ていた。', reading: 'トムはコートをきていた。', en: 'Tom was wearing a coat.', uses: ['g:te-ita', 'g:te-form', 'k:着', 'v:着る|きる', 'v:コート|コート'], furigana: 'トムはコートを[着|き]ていた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 8919230, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-ita-denwa', kind: 'sentence', level: 'N4', jp: 'きのうの夜、ともだちと電話で話していました。', reading: 'きのうのよる、ともだちとでんわではなしていました。', en: 'Last night I was talking with a friend on the phone.', uses: ['g:te-ita', 'g:te-form', 'k:夜', 'k:電', 'k:話', 'v:電話|でんわ', 'v:話す|はなす', 'v:夜|よる', 'v:昨日|きのう', 'v:友達|ともだち'], furigana: 'きのうの[夜|よる]、ともだちと[電話|でんわ]で[話|はな]していました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10899511', kind: 'sentence', level: 'N4', jp: 'あの人は日本語の先生だと思います。', reading: 'あのひとはにほんごのせんせいだとおもいます。', en: 'I think that person is a Japanese teacher.', uses: ['g:to-omou', 'k:人', 'k:日', 'k:本', 'k:語', 'k:先', 'k:生', 'k:思', 'v:あの|あの', 'v:先生|せんせい', 'v:人|ひと', 'v:思う|おもう'], furigana: 'あの[人|ひと]は[日本語|に|ほん|ご]の[先生|せん|せい]だと[思|おも]います。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12796478, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:171704', kind: 'sentence', level: 'N4', jp: '今日は雨になると思います。', reading: 'きょうはあめになるとおもいます。', en: 'We expect that it will rain today.', uses: ['g:to-omou', 'g:naru', 'k:今', 'k:日', 'k:雨', 'k:思', 'v:雨|あめ', 'v:今日|きょう', 'v:思う|おもう', 'v:なる|なる'], furigana: '[今日|きょう]は[雨|あめ]になると[思|おも]います。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 242771, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:2121372', kind: 'sentence', level: 'N4', jp: 'それはいい考えだと思います。', reading: 'それはいいかんがえだとおもいます。', en: 'I think that\'s a good idea.', uses: ['g:to-omou', 'k:考', 'k:思', 'v:いい|いい', 'v:それ|それ', 'v:思う|おもう', 'v:考える|かんがえる'], furigana: 'それはいい[考|かんが]えだと[思|おも]います。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1887725, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:161836', kind: 'sentence', level: 'N4', jp: 'あなたが悪いと思います。', reading: 'あなたがわるいとおもいます。', en: 'I think that you\'re to blame.', uses: ['g:to-omou', 'k:悪', 'k:思', 'v:あなた|あなた', 'v:悪い|わるい', 'v:思う|おもう'], furigana: 'あなたが[悪|わる]いと[思|おも]います。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 8264154, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10671730', kind: 'sentence', level: 'N4', jp: '来るって言ってますよ。', reading: 'くるっていってますよ。', en: 'He says he will come.', uses: ['g:tte', 'g:te-form', 'k:来', 'k:言', 'v:言う|いう', 'v:来る|くる'], furigana: '[来|く]るって[言|い]ってますよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 304538, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-tte-otoutosan', kind: 'sentence', level: 'N4', jp: '弟さんの名前って何？', reading: 'おとうとさんのなまえってなに？', en: "What's your younger brother's name?", uses: ['g:tte', 'k:弟', 'k:名', 'k:前', 'k:何', 'v:弟|おとうと', 'v:名前|なまえ', 'v:何|なに'], furigana: '[弟|おとうと]さんの[名前|な|まえ]って[何|なに]？', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:9725630', kind: 'sentence', level: 'N4', jp: '日本ってどう思う？', reading: 'にほんってどうおもう？', en: 'What do you think about Japan?', uses: ['g:tte', 'k:日', 'k:本', 'k:思', 'v:思う|おもう', 'v:どう|どう'], furigana: '[日本|に|ほん]ってどう[思|おも]う？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9725623, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:3481397', kind: 'sentence', level: 'N4', jp: 'これは何という花ですか？', reading: 'これはなんというはなですか？', en: 'What\'s this flower called?', uses: ['g:to-iu', 'k:何', 'k:花', 'v:これ|これ', 'v:何|なん', 'v:花|はな'], furigana: 'これは[何|なん]という[花|はな]ですか？', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 3481439, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:211000', kind: 'sentence', level: 'N4', jp: 'その犬はジョンという名前です。', reading: 'そのいぬはジョンというなまえです。', en: 'The dog\'s name is John.', uses: ['g:to-iu', 'k:犬', 'k:名', 'k:前', 'v:犬|いぬ', 'v:その|その', 'v:名前|なまえ'], furigana: 'その[犬|いぬ]はジョンという[名前|な|まえ]です。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10466975, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:233719', kind: 'sentence', level: 'N4', jp: 'あなたに会いたいという人がいます。', reading: 'あなたにあいたいというひとがいます。', en: 'There\'s somebody who wants to meet you.', uses: ['g:to-iu', 'g:tai', 'k:会', 'k:人', 'v:会う|あう', 'v:あなた|あなた', 'v:人|ひと'], furigana: 'あなたに[会|あ]いたいという[人|ひと]がいます。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 71092, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-koto-shumi', kind: 'sentence', level: 'N4', jp: 'わたしのしゅみは音楽を聞くことです。', reading: 'わたしのしゅみはおんがくをきくことです。', en: 'My hobby is listening to music.', uses: ['g:koto', 'k:音', 'k:楽', 'k:聞', 'v:音楽|おんがく', 'v:聞く|きく', 'v:私|わたし', 'v:趣味|しゅみ'], furigana: 'わたしのしゅみは[音楽|おんがく]を[聞|き]くことです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:81616', kind: 'sentence', level: 'N4', jp: '本を読むことは大切です。', reading: 'ほんをよむことはたいせつです。', en: 'It\'s important to read books.', uses: ['g:koto', 'k:本', 'k:読', 'k:大', 'k:切', 'v:大切|たいせつ', 'v:本|ほん', 'v:読む|よむ'], furigana: '[本|ほん]を[読|よ]むことは[大切|たい|せつ]です。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1439744, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:184779', kind: 'sentence', level: 'N4', jp: '外国語を学ぶことは楽しいよ。', reading: 'がいこくごをまなぶことはたのしいよ。', en: 'Learning a foreign language is fun.', uses: ['g:koto', 'k:外', 'k:国', 'k:語', 'k:学', 'k:楽', 'v:外国|がいこく', 'v:楽しい|たのしい'], furigana: '[外国|がい|こく][語|ご]を[学|まな]ぶことは[楽|たの]しいよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 21909, enAuthor: 'sacredceltic', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:161813', kind: 'sentence', level: 'N4', jp: 'あなたが先生だということを知っています。', reading: 'あなたがせんせいだということをしっています。', en: 'I know that you are a teacher.', uses: ['g:to-iu-koto', 'g:te-iru', 'g:te-form', 'k:先', 'k:生', 'k:知', 'v:あなた|あなた', 'v:知る|しる', 'v:先生|せんせい'], furigana: 'あなたが[先生|せん|せい]だということを[知|し]っています。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 252703, enAuthor: 'CC', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:79848', kind: 'sentence', level: 'N4', jp: '問題はお金がないということです。', reading: 'もんだいはおかねがないということです。', en: 'The trouble is that we have no money.', uses: ['g:to-iu-koto', 'k:問', 'k:題', 'k:金', 'v:お金|おかね', 'v:問題|もんだい', 'v:ない|ない'], furigana: '[問題|もん|だい]はお[金|かね]がないということです。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 243466, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-to-iu-koto-test', kind: 'sentence', level: 'N4', jp: 'あしたテストがないということを聞きました。', reading: 'あしたテストがないということをききました。', en: 'I heard that there\'s no test tomorrow.', uses: ['g:to-iu-koto', 'g:nai-form', 'k:聞', 'v:聞く|きく', 'v:テスト|テスト', 'v:明日|あした', 'v:ない|ない'], furigana: 'あしたテストがないということを[聞|き]きました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-shi-mise', kind: 'sentence', level: 'N4', jp: 'この店は安いし、おいしいし、よく来ます。', reading: 'このみせはやすいし、おいしいし、よくきます。', en: 'This place is cheap and the food is good, so I come here a lot.', uses: ['g:shi', 'k:店', 'k:安', 'k:来', 'v:おいしい|おいしい', 'v:来る|くる', 'v:この|この', 'v:店|みせ', 'v:安い|やすい', 'v:よく|よく'], furigana: 'この[店|みせ]は[安|やす]いし、おいしいし、よく[来|き]ます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-shi-heya', kind: 'sentence', level: 'N4', jp: 'このへやは広いし、駅にも近いです。', reading: 'このへやはひろいし、えきにもちかいです。', en: 'This room is big, and it\'s close to the station too.', uses: ['g:shi', 'k:広', 'k:駅', 'k:近', 'v:駅|えき', 'v:この|この', 'v:近い|ちかい', 'v:広い|ひろい', 'v:部屋|へや'], furigana: 'このへやは[広|ひろ]いし、[駅|えき]にも[近|ちか]いです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:224297', kind: 'sentence', level: 'N4', jp: 'ここは食べ物もおいしいし、サービスもよい。', reading: 'ここはたべものもおいしいし、サービスもよい。', en: 'The food is good, and service is good here.', uses: ['g:shi', 'k:食', 'k:物', 'v:おいしい|おいしい', 'v:ここ|ここ', 'v:食べ物|たべもの', 'v:物|もの', 'v:よい|よい'], furigana: 'ここは[食|た]べ[物|もの]もおいしいし、サービスもよい。', author: 'tommy__san', license: 'CC BY 2.0 FR', enId: 61632, enAuthor: 'kroko', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10969586', kind: 'sentence', level: 'N4', jp: 'その映画は見てないし、見たくもないよ。', reading: 'そのえいがはみてないし、みたくもないよ。', en: 'I haven\'t seen the movie, nor do I want to.', uses: ['g:shi', 'g:te-form', 'k:映', 'k:画', 'k:見', 'v:映画|えいが', 'v:その|その', 'v:見る|みる', 'v:ない|ない'], furigana: 'その[映画|えい|が]は[見|み]てないし、[見|み]たくもないよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 254231, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1866547', kind: 'sentence', level: 'N4', jp: 'そのための時間はないし、それにお金もないんだ。', reading: 'そのためのじかんはないし、それにおかねもないんだ。', en: 'I have no time for that, and besides, I don\'t have any money.', uses: ['g:shi', 'g:sore-ni', 'k:時', 'k:間', 'k:金', 'v:お金|おかね', 'v:時間|じかん', 'v:その|その', 'v:それに|それに', 'v:ない|ない'], furigana: 'そのための[時間|じ|かん]はないし、それにお[金|かね]もないんだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 436681, enAuthor: 'lukaszpp', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nado-suupaa', kind: 'sentence', level: 'N4', jp: 'スーパーで肉や魚などを買いました。', reading: 'スーパーでにくやさかななどをかいました。', en: 'At the supermarket I bought meat, fish and so on.', uses: ['g:nado', 'g:ya', 'k:肉', 'k:魚', 'k:買', 'v:買う|かう', 'v:魚|さかな', 'v:肉|にく', 'v:スーパー|スーパー', 'v:など|など'], furigana: 'スーパーで[肉|にく]や[魚|さかな]などを[買|か]いました。', chunks: { pre: 'スーパーで', move: ['肉や', '魚', 'などを', '買いました'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-nado-tsukue', kind: 'sentence', level: 'N4', jp: 'つくえの上に本やノートなどがあります。', reading: 'つくえのうえにほんやノートなどがあります。', en: 'There are books, notebooks and other things on the desk.', uses: ['g:nado', 'g:ya', 'g:ga-arimasu', 'k:上', 'k:本', 'v:上|うえ', 'v:ノート|ノート', 'v:本|ほん', 'v:机|つくえ', 'v:など|など'], furigana: 'つくえの[上|うえ]に[本|ほん]やノートなどがあります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:1987791', kind: 'sentence', level: 'N4', jp: 'お茶などいかがでしょう。', reading: 'おちゃなどいかがでしょう。', en: 'Would you like tea or something?', uses: ['g:nado', 'g:deshou', 'k:茶', 'v:いかが|いかが', 'v:お茶|おちゃ', 'v:など|など'], furigana: 'お[茶|ちゃ]などいかがでしょう。', author: 'e4zh1nmcz', license: 'CC BY 2.0 FR', enId: 1987792, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-toka-yasumi', kind: 'sentence', level: 'N4', jp: '休みの日は、そうじとかせんたくとかをします。', reading: 'やすみのひは、そうじとかせんたくとかをします。', en: 'On my days off I do things like cleaning and laundry.', uses: ['g:toka-toka', 'k:休', 'k:日', 'v:休み|やすみ', 'v:日|ひ', 'v:掃除|そうじ', 'v:洗濯|せんたく'], furigana: '[休|やす]みの[日|ひ]は、そうじとかせんたくとかをします。', chunks: { pre: '休みの日は、', move: ['そうじとか', 'せんたく', 'とかを', 'します'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-toka-ryouri', kind: 'sentence', level: 'N4', jp: 'すしとかてんぷらとか、日本の料理がすきです。', reading: 'すしとかてんぷらとか、にほんのりょうりがすきです。', en: 'I like Japanese food, like sushi and tempura.', uses: ['g:toka-toka', 'k:日', 'k:本', 'k:料', 'k:理', 'v:料理|りょうり', 'v:好き|すき'], furigana: 'すしとかてんぷらとか、[日本|にほん]の[料理|りょうり]がすきです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-toka-pen', kind: 'sentence', level: 'N4', jp: 'ペンとかノートとか、何か書くものがありますか。', reading: 'ペンとかノートとか、なにかかくものがありますか。', en: 'Do you have something to write with, like a pen or a notebook?', uses: ['g:toka-toka', 'g:noun-modifier', 'k:何', 'k:書', 'v:書く|かく', 'v:何|なに', 'v:ノート|ノート', 'v:ペン|ペン', 'v:物|もの'], furigana: 'ペンとかノートとか、[何|なに]か[書|か]くものがありますか。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-dake-de-uta', kind: 'sentence', level: 'N4', jp: 'この歌は聞いているだけで楽しくなります。', reading: 'このうたはきいているだけでたのしくなります。', en: 'Just listening to this song makes me happy.', uses: ['g:dake-de', 'g:te-iru', 'g:te-form', 'g:naru', 'k:歌', 'k:聞', 'k:楽', 'v:歌|うた', 'v:聞く|きく', 'v:この|この', 'v:楽しい|たのしい', 'v:なる|なる', 'v:だけ|だけ'], furigana: 'この[歌|うた]は[聞|き]いているだけで[楽|たの]しくなります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10808978', kind: 'sentence', level: 'N4', jp: 'この紙にサインするだけでいいんだよ。', reading: 'このかみにサインするだけでいいんだよ。', en: 'All you have to do is sign this paper.', uses: ['g:dake-de', 'k:紙', 'v:いい|いい', 'v:紙|かみ', 'v:この|この', 'v:だけ|だけ', 'v:する|する'], furigana: 'この[紙|かみ]にサインするだけでいいんだよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 16683, enAuthor: 'iamgrim', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9042473', kind: 'sentence', level: 'N4', jp: '二人だけで話したいんだけど。', reading: 'ふたりだけではなしたいんだけど。', en: 'I want to talk with you in private.', uses: ['g:dake-de', 'g:tai', 'k:二', 'k:人', 'k:話', 'v:話す|はなす', 'v:二人|ふたり', 'v:だけ|だけ'], furigana: '[二人|ふた|り]だけで[話|はな]したいんだけど。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10179061, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1683201', kind: 'sentence', level: 'N4', jp: '二人だけで話があります。', reading: 'ふたりだけではなしがあります。', en: 'I\'d like a word with you in private.', uses: ['g:dake-de', 'g:ga-arimasu', 'k:二', 'k:人', 'k:話', 'v:話|はなし', 'v:二人|ふたり', 'v:だけ|だけ'], furigana: '[二人|ふたり]だけで[話|はなし]があります。', author: 'aka_aj', license: 'CC BY 2.0 FR', enId: 1682834, enAuthor: 'Spamster', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-sore-ni-mise', kind: 'sentence', level: 'N4', jp: 'この店は安いです。それに、とてもおいしいです。', reading: 'このみせはやすいです。それに、とてもおいしいです。', en: 'This place is cheap. On top of that, it\'s really good.', uses: ['g:sore-ni', 'k:店', 'k:安', 'v:おいしい|おいしい', 'v:この|この', 'v:とても|とても', 'v:店|みせ', 'v:安い|やすい', 'v:それに|それに'], furigana: 'この[店|みせ]は[安|やす]いです。それに、とてもおいしいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-sore-ni-ame', kind: 'sentence', level: 'N4', jp: '今日は雨です。それに、さむいです。', reading: 'きょうはあめです。それに、さむいです。', en: 'It\'s raining today. And on top of that, it\'s cold.', uses: ['g:sore-ni', 'k:今', 'k:日', 'k:雨', 'v:雨|あめ', 'v:今日|きょう', 'v:それに|それに', 'v:寒い|さむい'], furigana: '[今日|きょう]は[雨|あめ]です。それに、さむいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-sore-demo-ame', kind: 'sentence', level: 'N4', jp: '雨がふっていました。それでも、こどもたちは外であそびました。', reading: 'あめがふっていました。それでも、こどもたちはそとであそびました。', en: 'It was raining. Even so, the children played outside.', uses: ['g:sore-demo', 'g:te-ita', 'g:te-form', 'k:雨', 'k:外', 'v:雨|あめ', 'v:外|そと', 'v:降る|ふる', 'v:子供|こども', 'v:遊ぶ|あそぶ'], furigana: '[雨|あめ]がふっていました。それでも、こどもたちは[外|そと]であそびました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-sore-demo-test', kind: 'sentence', level: 'N4', jp: 'たくさん勉強しました。それでも、テストはむずかしかったです。', reading: 'たくさんべんきょうしました。それでも、テストはむずかしかったです。', en: 'I studied a lot. Even so, the test was hard.', uses: ['g:sore-demo', 'k:勉', 'k:強', 'v:たくさん|たくさん', 'v:テスト|テスト', 'v:難しい|むずかしい'], furigana: 'たくさん[勉強|べんきょう]しました。それでも、テストはむずかしかったです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-sore-demo-shukudai', kind: 'sentence', level: 'N4', jp: 'とてもつかれていました。それでも、しゅくだいをしました。', reading: 'とてもつかれていました。それでも、しゅくだいをしました。', en: 'I was very tired. Even so, I did my homework.', uses: ['g:sore-demo', 'g:te-ita', 'g:te-form', 'v:とても|とても', 'v:疲れる|つかれる', 'v:宿題|しゅくだい', 'v:する|する'], furigana: 'とてもつかれていました。それでも、しゅくだいをしました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11619795', kind: 'sentence', level: 'N4', jp: 'それでも、そこに行ってみたい。', reading: 'それでも、そこにいってみたい。', en: 'Nevertheless, I want to go there.', uses: ['g:sore-demo', 'g:te-miru', 'g:tai', 'g:te-form', 'k:行', 'v:そこ|そこ'], furigana: 'それでも、そこに[行|い]ってみたい。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 456497, enAuthor: 'lukaszpp', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8534126', kind: 'sentence', level: 'N4', jp: '何でも食べます。', reading: 'なんでもたべます。', en: 'I\'ll eat anything.', uses: ['g:demo', 'k:何', 'k:食', 'v:食べる|たべる', 'v:何|なん'], furigana: '[何|なん]でも[食|た]べます。', author: 'e4zh1nmcz', license: 'CC BY 2.0 FR', enId: 3844661, enAuthor: 'Youmu970', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-demo-koohii', kind: 'sentence', level: 'N4', jp: 'コーヒーでも飲みませんか。', reading: 'コーヒーでものみませんか。', en: 'Would you like a coffee or something?', uses: ['g:demo', 'g:masen-ka', 'k:飲', 'v:コーヒー|コーヒー', 'v:飲む|のむ'], furigana: 'コーヒーでも[飲|の]みませんか。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:2992032', kind: 'sentence', level: 'N4', jp: 'いつでも来ていいよ。', reading: 'いつでもきていいよ。', en: 'Come anytime you like.', uses: ['g:demo', 'g:te-form', 'k:来', 'v:いつ|いつ', 'v:来る|くる', 'v:いい|いい'], furigana: 'いつでも[来|き]ていいよ。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 2992102, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-demo-dare', kind: 'sentence', level: 'N4', jp: 'その歌は、だれでも知っています。', reading: 'そのうたは、だれでもしっています。', en: 'Everyone knows that song.', uses: ['g:demo', 'g:te-iru', 'g:te-form', 'k:歌', 'k:知', 'v:歌|うた', 'v:知る|しる', 'v:その|その', 'v:誰|だれ'], furigana: 'その[歌|うた]は、だれでも[知|し]っています。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-ga-hoshii-kaban', kind: 'sentence', level: 'N4', jp: 'わたしは新しいかばんがほしいです。', reading: 'わたしはあたらしいかばんがほしいです。', en: 'I want a new bag.', uses: ['g:ga-hoshii', 'k:新', 'v:新しい|あたらしい', 'v:かばん|かばん', 'v:私|わたし', 'v:欲しい|ほしい'], furigana: 'わたしは[新|あたら]しいかばんがほしいです。', chunks: { pre: 'わたしは', move: ['新しい', 'かばん', 'が', 'ほしい'], post: 'です。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:151216', kind: 'sentence', level: 'N4', jp: '紙がほしい。', reading: 'かみがほしい。', en: 'I want some paper.', uses: ['g:ga-hoshii', 'k:紙', 'v:紙|かみ', 'v:欲しい|ほしい'], furigana: '[紙|かみ]がほしい。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1273366, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:161578', kind: 'sentence', level: 'N4', jp: 'あの犬の写真がほしいな。', reading: 'あのいぬのしゃしんがほしいな。', en: 'I want a picture of that dog.', uses: ['g:ga-hoshii', 'k:犬', 'k:写', 'k:真', 'v:あの|あの', 'v:犬|いぬ', 'v:写真|しゃしん', 'v:欲しい|ほしい'], furigana: 'あの[犬|いぬ]の[写真|しゃ|しん]がほしいな。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 252938, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:187929', kind: 'sentence', level: 'N4', jp: '何か新しいものがほしい。', reading: 'なにかあたらしいものがほしい。', en: 'I want something new.', uses: ['g:ga-hoshii', 'k:何', 'k:新', 'v:新しい|あたらしい', 'v:何|なに', 'v:物|もの', 'v:欲しい|ほしい'], furigana: '[何|なに]か[新|あたら]しいものがほしい。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 3822079, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-hoshii-matsu', kind: 'sentence', level: 'N4', jp: 'もう少し待ってほしいです。', reading: 'もうすこしまってほしいです。', en: 'I\'d like you to wait a little longer.', uses: ['g:te-hoshii', 'g:te-form', 'k:少', 'k:待', 'v:少し|すこし', 'v:待つ|まつ', 'v:もう|もう', 'v:欲しい|ほしい'], furigana: 'もう[少|すこ]し[待|ま]ってほしいです。', chunks: { pre: '', move: ['もう', '少し', '待って', 'ほしい'], post: 'です。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:157464', kind: 'sentence', level: 'N4', jp: 'すぐ来てほしい。', reading: 'すぐきてほしい。', en: 'I want you to come at once.', uses: ['g:te-hoshii', 'g:te-form', 'k:来', 'v:来る|くる', 'v:欲しい|ほしい'], furigana: 'すぐ[来|き]てほしい。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 257068, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1152237', kind: 'sentence', level: 'N4', jp: 'あなたに歌ってほしい。', reading: 'あなたにうたってほしい。', en: 'I want you to sing.', uses: ['g:te-hoshii', 'g:te-form', 'k:歌', 'v:あなた|あなた', 'v:歌う|うたう', 'v:欲しい|ほしい'], furigana: 'あなたに[歌|うた]ってほしい。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1062745, enAuthor: 'Zifre', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:164300', kind: 'sentence', level: 'N4', jp: '私のいとこに会ってほしいんです。', reading: 'わたしのいとこにあってほしいんです。', en: 'I want you to meet my cousin.', uses: ['g:te-hoshii', 'g:te-form', 'k:私', 'k:会', 'v:会う|あう', 'v:私|わたし', 'v:欲しい|ほしい'], furigana: '[私|わたし]のいとこに[会|あ]ってほしいんです。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 250209, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-tagaru-otouto', kind: 'sentence', level: 'N4', jp: '弟はいつも外であそびたがります。', reading: 'おとうとはいつもそとであそびたがります。', en: 'My little brother always wants to play outside.', uses: ['g:tagaru', 'k:弟', 'k:外', 'v:いつも|いつも', 'v:弟|おとうと', 'v:外|そと', 'v:遊ぶ|あそぶ'], furigana: '[弟|おとうと]はいつも[外|そと]であそびたがります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10796446', kind: 'sentence', level: 'N4', jp: '父が会いたがっています。', reading: 'ちちがあいたがっています。', en: 'My dad would like to meet you.', uses: ['g:tagaru', 'g:te-iru', 'g:te-form', 'k:父', 'k:会', 'v:会う|あう', 'v:父|ちち'], furigana: '[父|ちち]が[会|あ]いたがっています。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 8689209, enAuthor: 'shekitten', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:2662459', kind: 'sentence', level: 'N4', jp: 'トムは電車で行きたがっている。', reading: 'トムはでんしゃでいきたがっている。', en: 'Tom wants to go by train.', uses: ['g:tagaru', 'g:te-iru', 'g:te-form', 'k:電', 'k:車', 'k:行', 'v:行く|いく', 'v:電車|でんしゃ'], furigana: 'トムは[電車|でん|しゃ]で[行|い]きたがっている。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 2662406, enAuthor: 'sharptoothed', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9752002', kind: 'sentence', level: 'N4', jp: 'トムはフランス語を習いたがった。', reading: 'トムはフランスごをならいたがった。', en: 'Tom wanted to learn French.', uses: ['g:tagaru', 'k:語', 'k:習', 'v:習う|ならう', 'v:語|ご'], furigana: 'トムはフランス[語|ご]を[習|なら]いたがった。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 6269872, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-ga-suru-nioi', kind: 'sentence', level: 'N4', jp: 'キッチンから、いいにおいがします。', reading: 'キッチンから、いいにおいがします。', en: 'There\'s a nice smell coming from the kitchen.', uses: ['g:ga-suru', 'v:いい|いい', 'v:匂い|におい', 'v:する|する'], furigana: 'キッチンから、いいにおいがします。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11483540', kind: 'sentence', level: 'N4', jp: '風の音がする。', reading: 'かぜのおとがする。', en: 'I hear the wind blow.', uses: ['g:ga-suru', 'k:風', 'k:音', 'v:風|かぜ', 'v:音|おと', 'v:する|する'], furigana: '[風|かぜ]の[音|おと]がする。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10738328, enAuthor: 'Cabo', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:223647', kind: 'sentence', level: 'N4', jp: 'このスープは魚の味がする。', reading: 'このスープはさかなのあじがする。', en: 'This soup tastes like fish.', uses: ['g:ga-suru', 'k:魚', 'k:味', 'v:この|この', 'v:魚|さかな', 'v:味|あじ', 'v:する|する'], furigana: 'このスープは[魚|さかな]の[味|あじ]がする。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 1338765, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:2478353', kind: 'sentence', level: 'N4', jp: 'ドアが開く音がした。', reading: 'ドアがあくおとがした。', en: 'I heard the door open.', uses: ['g:ga-suru', 'g:noun-modifier', 'k:開', 'k:音', 'v:開く|あく', 'v:音|おと', 'v:ドア|ドア', 'v:する|する'], furigana: 'ドアが[開|あ]く[音|おと]がした。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 239918, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8505146', kind: 'sentence', level: 'N4', jp: '何か食べたい気がする。', reading: 'なにかたべたいきがする。', en: 'I feel like eating something.', uses: ['g:ga-suru', 'g:tai', 'g:noun-modifier', 'k:何', 'k:食', 'k:気', 'v:食べる|たべる', 'v:何|なに', 'v:気|き', 'v:する|する'], furigana: '[何|なに]か[食|た]べたい[気|き]がする。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 256363, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-sa-yama', kind: 'sentence', level: 'N4', jp: 'この山の高さは三千メートルです。', reading: 'このやまのたかさはさんぜんメートルです。', en: 'The height of this mountain is 3,000 meters.', uses: ['g:sa', 'k:山', 'k:高', 'k:三', 'k:千', 'v:この|この', 'v:高い|たかい', 'v:メートル|メートル', 'v:山|やま', 'v:三|さん', 'v:千|せん'], furigana: 'この[山|やま]の[高|たか]さは[三千|さんぜん]メートルです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:218746', kind: 'sentence', level: 'N4', jp: 'これとあれは同じ長さです。', reading: 'これとあれはおなじながさです。', en: 'This one and that one are the same length.', uses: ['g:sa', 'k:同', 'k:長', 'v:あれ|あれ', 'v:同じ|おなじ', 'v:これ|これ', 'v:長い|ながい'], furigana: 'これとあれは[同|おな]じ[長|なが]さです。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12602160, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:210451', kind: 'sentence', level: 'N4', jp: 'その山はどれくらいの高さですか。', reading: 'そのやまはどれくらいのたかさですか。', en: 'How high is the mountain?', uses: ['g:sa', 'k:山', 'k:高', 'v:その|その', 'v:高い|たかい', 'v:どれ|どれ', 'v:山|やま', 'v:くらい|くらい'], furigana: 'その[山|やま]はどれくらいの[高|たか]さですか。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 47719, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-sa-kaban', kind: 'sentence', level: 'N4', jp: 'この二つのかばんは同じ重さです。', reading: 'このふたつのかばんはおなじおもさです。', en: 'These two bags are the same weight.', uses: ['g:sa', 'k:二', 'k:同', 'k:重', 'v:この|この', 'v:二つ|ふたつ', 'v:かばん|かばん', 'v:同じ|おなじ', 'v:重い|おもい'], furigana: 'この[二|ふた]つのかばんは[同|おな]じ[重|おも]さです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-sou-da-looks-keeki', kind: 'sentence', level: 'N4', jp: 'このケーキはおいしそうですね。', reading: 'このケーキはおいしそうですね。', en: 'This cake looks delicious, doesn\'t it?', uses: ['g:sou-da-looks', 'g:ne', 'v:おいしい|おいしい', 'v:この|この', 'v:ケーキ|ケーキ'], furigana: 'このケーキはおいしそうですね。', chunks: { pre: '', move: ['この', 'ケーキは', 'おいし', 'そうですね'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:227830', kind: 'sentence', level: 'N4', jp: 'おいしそうな料理ですね。', reading: 'おいしそうなりょうりですね。', en: 'It looks appetizing.', uses: ['g:sou-da-looks', 'k:料', 'k:理', 'v:おいしい|おいしい', 'v:料理|りょうり'], furigana: 'おいしそうな[料理|りょう|り]ですね。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 65183, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:216464', kind: 'sentence', level: 'N4', jp: 'ジェーンは楽しそうだ。', reading: 'ジェーンはたのしそうだ。', en: 'Jane looks happy.', uses: ['g:sou-da-looks', 'k:楽', 'v:楽しい|たのしい'], furigana: 'ジェーンは[楽|たの]しそうだ。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 53761, enAuthor: 'CN', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:80451', kind: 'sentence', level: 'N4', jp: '明日は雨になりそうだ。', reading: 'あしたはあめになりそうだ。', en: 'It looks like it\'s going to rain tomorrow.', uses: ['g:sou-da-looks', 'g:naru', 'k:明', 'k:日', 'k:雨', 'v:明日|あした', 'v:雨|あめ', 'v:なる|なる'], furigana: '[明日|あした]は[雨|あめ]になりそうだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 5313328, enAuthor: 'tabular', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10809041', kind: 'sentence', level: 'N4', jp: 'よさそうな家だよ。', reading: 'よさそうないえだよ。', en: 'It looks like a nice house.', uses: ['g:sou-da-looks', 'k:家', 'v:家|いえ'], furigana: 'よさそうな[家|いえ]だよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 12740151, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:184879', kind: 'sentence', level: 'N4', jp: '外は、夏みたいだよ。', reading: 'そとは、なつみたいだよ。', en: 'It\'s like summer outside.', uses: ['g:mitai', 'k:外', 'k:夏', 'v:外|そと', 'v:夏|なつ'], furigana: '[外|そと]は、[夏|なつ]みたいだよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 22010, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11052242', kind: 'sentence', level: 'N4', jp: 'この犬、病気みたい。', reading: 'このいぬ、びょうきみたい。', en: 'This dog looks sick.', uses: ['g:mitai', 'k:犬', 'k:病', 'k:気', 'v:犬|いぬ', 'v:この|この', 'v:病気|びょうき'], furigana: 'この[犬|いぬ]、[病気|びょう|き]みたい。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9741458, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:12054409', kind: 'sentence', level: 'N4', jp: '楽しかったみたいね。', reading: 'たのしかったみたいね。', en: 'It sounds like you had fun.', uses: ['g:mitai', 'k:楽', 'v:楽しい|たのしい'], furigana: '[楽|たの]しかったみたいね。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12069372, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-mitai-ani', kind: 'sentence', level: 'N4', jp: '兄は外国の人みたいに英語を話します。', reading: 'あにはがいこくのひとみたいにえいごをはなします。', en: 'My older brother speaks English like someone from abroad.', uses: ['g:mitai', 'k:兄', 'k:外', 'k:国', 'k:人', 'k:英', 'k:語', 'k:話', 'v:兄|あに', 'v:英語|えいご', 'v:外国|がいこく', 'v:話す|はなす', 'v:人|ひと'], furigana: '[兄|あに]は[外国|がいこく]の[人|ひと]みたいに[英語|えいご]を[話|はな]します。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:171129', kind: 'sentence', level: 'N4', jp: '今夜は雨のようだ。', reading: 'こんやはあめのようだ。', en: 'I\'m afraid it\'ll rain tonight.', uses: ['g:you-da', 'k:今', 'k:夜', 'k:雨', 'v:雨|あめ', 'v:今夜|こんや'], furigana: '[今夜|こん|や]は[雨|あめ]のようだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 243350, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:171535', kind: 'sentence', level: 'N4', jp: '今日は店は休みのようだ。', reading: 'きょうはみせはやすみのようだ。', en: 'The shop seems to be closed today.', uses: ['g:you-da', 'k:今', 'k:日', 'k:店', 'k:休', 'v:今日|きょう', 'v:店|みせ', 'v:休み|やすみ'], furigana: '[今日|きょう]は[店|みせ]は[休|やす]みのようだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 12070345, enAuthor: 'sundown', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:230329', kind: 'sentence', level: 'N4', jp: 'あまり元気じゃないようだね。', reading: 'あまりげんきじゃないようだね。', en: 'You don\'t look so well.', uses: ['g:you-da', 'g:amari-nai', 'g:ja-nai', 'k:元', 'k:気', 'v:あまり|あまり', 'v:元気|げんき'], furigana: 'あまり[元気|げん|き]じゃないようだね。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 2283661, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:3367120', kind: 'sentence', level: 'N4', jp: '楽しんでいるようだね。', reading: 'たのしんでいるようだね。', en: 'It looks like you\'re having fun.', uses: ['g:you-da', 'g:te-iru', 'g:te-form', 'k:楽'], furigana: '[楽|たの]しんでいるようだね。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 12826198, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-no-you-na-isha', kind: 'sentence', level: 'N4', jp: '父のような医者になりたいです。', reading: 'ちちのようないしゃになりたいです。', en: 'I want to become a doctor like my father.', uses: ['g:no-you-na', 'g:tai', 'g:naru', 'k:父', 'k:医', 'k:者', 'v:医者|いしゃ', 'v:父|ちち', 'v:なる|なる'], furigana: '[父|ちち]のような[医者|いしゃ]になりたいです。', chunks: { pre: '', move: ['父', 'のような', '医者に', 'なりたい'], post: 'です。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:12296469', kind: 'sentence', level: 'N4', jp: 'レモンのような味がする。', reading: 'レモンのようなあじがする。', en: 'It tastes like lemon.', uses: ['g:no-you-na', 'g:ga-suru', 'k:味', 'v:味|あじ', 'v:する|する'], furigana: 'レモンのような[味|あじ]がする。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10502492, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:4930', kind: 'sentence', level: 'N4', jp: 'またいつか風のように走るんだ。', reading: 'またいつかかぜのようにはしるんだ。', en: 'Someday I\'ll run like the wind.', uses: ['g:no-you-na', 'k:風', 'k:走', 'v:風|かぜ', 'v:走る|はしる', 'v:また|また'], furigana: 'またいつか[風|かぜ]のように[走|はし]るんだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1519, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-no-you-ni-haha', kind: 'sentence', level: 'N4', jp: 'わたしも母のように、うたが上手になりたいです。', reading: 'わたしもははのように、うたがじょうずになりたいです。', en: 'I want to be a good singer, like my mother.', uses: ['g:no-you-na', 'g:tai', 'g:naru', 'k:母', 'k:上', 'k:手', 'v:私|わたし', 'v:母|はは', 'v:歌|うた', 'v:上手|じょうず', 'v:なる|なる'], furigana: 'わたしも[母|はは]のように、うたが[上手|じょう|ず]になりたいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:233478', kind: 'sentence', level: 'N4', jp: 'あなたのように上手になりたいです。', reading: 'あなたのようにじょうずになりたいです。', en: 'I want to be a good player like you.', uses: ['g:no-you-na', 'g:tai', 'g:naru', 'k:上', 'k:手', 'v:あなた|あなた', 'v:上手|じょうず', 'v:なる|なる'], furigana: 'あなたのように[上手|じょう|ず]になりたいです。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 70849, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:161400', kind: 'sentence', level: 'N4', jp: '私はいつものように早く起きた。', reading: 'わたしはいつものようにはやくおきた。', en: 'I got up early as usual.', uses: ['g:no-you-na', 'g:ta-form', 'k:私', 'k:早', 'k:起', 'v:いつも|いつも', 'v:起きる|おきる', 'v:早い|はやい', 'v:私|わたし'], furigana: '[私|わたし]はいつものように[早|はや]く[起|お]きた。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 253117, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-sou-da-hearsay-ame', kind: 'sentence', level: 'N4', jp: 'あしたは雨だそうです。', reading: 'あしたはあめだそうです。', en: 'I hear it will rain tomorrow.', uses: ['g:sou-da-hearsay', 'k:雨', 'v:雨|あめ', 'v:明日|あした'], furigana: 'あしたは[雨|あめ]だそうです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:1594278', kind: 'sentence', level: 'N4', jp: 'トニーさんは高い車を買ったそうです。', reading: 'トニーさんはたかいくるまをかったそうです。', en: 'I\'ve heard that Tony bought an expensive car.', uses: ['g:sou-da-hearsay', 'g:ta-form', 'k:高', 'k:車', 'k:買', 'v:買う|かう', 'v:車|くるま', 'v:高い|たかい'], furigana: 'トニーさんは[高|たか]い[車|くるま]を[買|か]ったそうです。', author: 'FiRez', license: 'CC BY 2.0 FR', enId: 1608821, enAuthor: 'Bah_Dure', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:189072', kind: 'sentence', level: 'N4', jp: '英語を習っているそうですね。', reading: 'えいごをならっているそうですね。', en: 'I hear you are taking English lessons.', uses: ['g:sou-da-hearsay', 'g:te-iru', 'g:te-form', 'k:英', 'k:語', 'k:習', 'v:英語|えいご', 'v:習う|ならう', 'v:居る|いる'], furigana: '[英語|えい|ご]を[習|なら]っているそうですね。', author: 'tommy__san', license: 'CC BY 2.0 FR', enId: 26220, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-sou-da-hearsay-tomodachi', kind: 'sentence', level: 'N4', jp: 'ともだちの話では、あしたは雨になるそうです。', reading: 'ともだちのはなしでは、あしたはあめになるそうです。', en: 'My friend says it will rain tomorrow.', uses: ['g:sou-da-hearsay', 'g:naru', 'k:話', 'k:雨', 'v:友達|ともだち', 'v:話|はなし', 'v:明日|あした', 'v:雨|あめ', 'v:なる|なる'], furigana: 'ともだちの[話|はなし]では、あしたは[雨|あめ]になるそうです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-kamo-shirenai-yuki', kind: 'sentence', level: 'N4', jp: 'あしたはゆきがふるかもしれません。', reading: 'あしたはゆきがふるかもしれません。', en: 'It might snow tomorrow.', uses: ['g:kamo-shirenai', 'v:明日|あした', 'v:雪|ゆき', 'v:降る|ふる'], furigana: 'あしたはゆきがふるかもしれません。', chunks: { pre: 'あしたは', move: ['ゆきが', 'ふる', 'かも', 'しれません'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:2363874', kind: 'sentence', level: 'N4', jp: '父は今家にいるかもしれません。', reading: 'ちちはいまいえにいるかもしれません。', en: 'My father may be at home now.', uses: ['g:kamo-shirenai', 'k:父', 'k:今', 'k:家', 'v:父|ちち', 'v:今|いま', 'v:家|いえ', 'v:居る|いる'], furigana: '[父|ちち]は[今|いま][家|いえ]にいるかもしれません。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 319132, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:234338', kind: 'sentence', level: 'N4', jp: 'トムは病気だったかもしれない。', reading: 'トムはびょうきだったかもしれない。', en: 'Tom may have been sick.', uses: ['g:kamo-shirenai', 'k:病', 'k:気', 'v:病気|びょうき'], furigana: 'トムは[病気|びょう|き]だったかもしれない。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 71713, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8897204', kind: 'sentence', level: 'N4', jp: '後からトムが来るかもしれないよ。', reading: 'あとからトムがくるかもしれないよ。', en: 'Tom might be here later.', uses: ['g:kamo-shirenai', 'k:後', 'k:来', 'v:後|あと', 'v:来る|くる'], furigana: '[後|あと]からトムが[来|く]るかもしれないよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 6786232, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:198131', kind: 'sentence', level: 'N4', jp: 'バスはすぐ来るはずです。', reading: 'バスはすぐくるはずです。', en: 'The bus should be coming soon.', uses: ['g:hazu', 'k:来', 'v:来る|くる', 'v:バス|バス', 'v:はず|はず'], furigana: 'バスはすぐ[来|く]るはずです。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 35321, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8579884', kind: 'sentence', level: 'N4', jp: 'トムは知ってるはずだ。', reading: 'トムはしってるはずだ。', en: 'Tom ought to know.', uses: ['g:hazu', 'k:知', 'v:知る|しる', 'v:はず|はず'], furigana: 'トムは[知|し]ってるはずだ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 4667194, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11173182', kind: 'sentence', level: 'N4', jp: 'そのタオルはきれいなはずです。', reading: 'そのタオルはきれいなはずです。', en: 'That towel should be clean.', uses: ['g:hazu', 'v:きれい|きれい', 'v:その|その', 'v:はず|はず'], furigana: 'そのタオルはきれいなはずです。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 11173178, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-hazu-tsuku', kind: 'sentence', level: 'N4', jp: '兄はもう駅に着いたはずです。', reading: 'あにはもうえきについたはずです。', en: 'My brother should have arrived at the station by now.', uses: ['g:hazu', 'g:ta-form', 'k:兄', 'k:駅', 'k:着', 'v:兄|あに', 'v:駅|えき', 'v:着く|つく', 'v:もう|もう', 'v:はず|はず'], furigana: '[兄|あに]はもう[駅|えき]に[着|つ]いたはずです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:141784', kind: 'sentence', level: 'N4', jp: '先生がそんなことを言ったはずがない。', reading: 'せんせいがそんなことをいったはずがない。', en: 'The teacher cannot have said such a thing.', uses: ['g:hazu-ga-nai', 'g:ta-form', 'k:先', 'k:生', 'k:言', 'v:言う|いう', 'v:先生|せんせい', 'v:そんな|そんな', 'v:事|こと', 'v:はず|はず'], furigana: '[先生|せん|せい]がそんなことを[言|い]ったはずがない。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 272786, enAuthor: 'CC', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11692639', kind: 'sentence', level: 'N4', jp: '正しいはずがないよ。', reading: 'ただしいはずがないよ。', en: 'That can\'t be right.', uses: ['g:hazu-ga-nai', 'k:正', 'v:正しい|ただしい', 'v:はず|はず'], furigana: '[正|ただ]しいはずがないよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1671761, enAuthor: 'Spamster', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:81586', kind: 'sentence', level: 'N4', jp: '本気のはずがないわ。', reading: 'ほんきのはずがないわ。', en: 'You cannot be serious.', uses: ['g:hazu-ga-nai', 'k:本', 'k:気', 'v:はず|はず'], furigana: '[本気|ほん|き]のはずがないわ。', author: 'mookeee', license: 'CC BY 2.0 FR', enId: 240209, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-hazu-ga-nai-shiranai', kind: 'sentence', level: 'N4', jp: 'トムさんが知らないはずがありません。', reading: 'トムさんがしらないはずがありません。', en: 'There\'s no way Tom doesn\'t know.', uses: ['g:hazu-ga-nai', 'g:nai-form', 'k:知', 'v:知る|しる', 'v:はず|はず'], furigana: 'トムさんが[知|し]らないはずがありません。', chunks: { pre: '', move: ['トムさんが', '知らない', 'はずが', 'ありません'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-yotei-da-natsuyasumi', kind: 'sentence', level: 'N4', jp: '夏休みに、海へ行くよていです。', reading: 'なつやすみに、うみへいくよていです。', en: 'I\'m planning to go to the sea over the summer vacation.', uses: ['g:yotei-da', 'k:夏', 'k:休', 'k:海', 'k:行', 'v:行く|いく', 'v:海|うみ', 'v:夏休み|なつやすみ', 'v:予定|よてい'], furigana: '[夏休|なつやす]みに、[海|うみ]へ[行|い]くよていです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-yotei-da-basu', kind: 'sentence', level: 'N4', jp: 'バスは九時に着くよていです。', reading: 'バスはくじにつくよていです。', en: 'The bus is scheduled to arrive at nine.', uses: ['g:yotei-da', 'k:九', 'k:時', 'k:着', 'v:着く|つく', 'v:予定|よてい', 'v:バス|バス'], furigana: 'バスは[九時|くじ]に[着|つ]くよていです。', chunks: { pre: 'バスは', move: ['九時に', '着く', 'よてい', 'です'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-yotei-da-kaigi', kind: 'sentence', level: 'N4', jp: 'かいぎは三時に終わるよていです。', reading: 'かいぎはさんじにおわるよていです。', en: 'The meeting is scheduled to end at three.', uses: ['g:yotei-da', 'k:三', 'k:時', 'k:終', 'v:終わる|おわる', 'v:予定|よてい', 'v:会議|かいぎ'], furigana: 'かいぎは[三時|さんじ]に[終|お]わるよていです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-potential-nihongo', kind: 'sentence', level: 'N4', jp: 'わたしは日本語が少し話せます。', reading: 'わたしはにほんごがすこしはなせます。', en: 'I can speak a little Japanese.', uses: ['g:potential', 'k:日', 'k:本', 'k:語', 'k:少', 'k:話', 'v:少し|すこし', 'v:話す|はなす', 'v:私|わたし'], furigana: 'わたしは[日本語|にほんご]が[少|すこ]し[話|はな]せます。', chunks: { pre: 'わたしは', move: ['日本語が', '少し', '話せ', 'ます'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-potential-korareru', kind: 'sentence', level: 'N4', jp: 'あしたのパーティーに来られますか。', reading: 'あしたのパーティーにこられますか。', en: 'Can you come to tomorrow\'s party?', uses: ['g:potential', 'k:来', 'v:来る|くる', 'v:パーティー|パーティー', 'v:明日|あした'], furigana: 'あしたのパーティーに[来|こ]られますか。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:158343', kind: 'sentence', level: 'N4', jp: '私は英語が話せる。', reading: 'わたしはえいごがはなせる。', en: 'I can speak English.', uses: ['g:potential', 'k:私', 'k:英', 'k:語', 'k:話', 'v:英語|えいご', 'v:話す|はなす', 'v:私|わたし'], furigana: '[私|わたし]は[英語|えい|ご]が[話|はな]せる。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 256187, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:226787', kind: 'sentence', level: 'N4', jp: 'お肉は食べられません。', reading: 'おにくはたべられません。', en: 'I can\'t eat meat.', uses: ['g:potential', 'k:肉', 'k:食', 'v:食べる|たべる', 'v:肉|にく'], furigana: 'お[肉|にく]は[食|た]べられません。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 64134, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10903672', kind: 'sentence', level: 'N4', jp: '私は漢字が書けます。', reading: 'わたしはかんじがかけます。', en: 'I can write kanji.', uses: ['g:potential', 'k:私', 'k:漢', 'k:字', 'k:書', 'v:書く|かく', 'v:漢字|かんじ', 'v:私|わたし'], furigana: '[私|わたし]は[漢字|かん|じ]が[書|か]けます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 10919503, enAuthor: 'tsp_2', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:220973', kind: 'sentence', level: 'N4', jp: 'この水は飲めます。', reading: 'このみずはのめます。', en: 'This water is drinkable.', uses: ['g:potential', 'k:水', 'k:飲', 'v:この|この', 'v:飲む|のむ', 'v:水|みず'], furigana: 'この[水|みず]は[飲|の]めます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 12593378, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:3456433', kind: 'sentence', level: 'N4', jp: '日本語を話すことができます。', reading: 'にほんごをはなすことができます。', en: 'I can speak Japanese.', uses: ['g:koto-ga-dekiru', 'g:koto', 'k:日', 'k:本', 'k:語', 'k:話', 'v:できる|できる', 'v:話す|はなす'], furigana: '[日本語|に|ほん|ご]を[話|はな]すことができます。', author: 'e4zh1nmcz', license: 'CC BY 2.0 FR', enId: 3456431, enAuthor: 'CN', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11013888', kind: 'sentence', level: 'N4', jp: 'ここで勉強することができます。', reading: 'ここでべんきょうすることができます。', en: 'You can study here.', uses: ['g:koto-ga-dekiru', 'g:koto', 'k:勉', 'k:強', 'v:ここ|ここ', 'v:できる|できる', 'v:する|する'], furigana: 'ここで[勉強|べん|きょう]することができます。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 16715, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10326041', kind: 'sentence', level: 'N4', jp: 'タワーはここから見ることができます。', reading: 'タワーはここからみることができます。', en: 'You can see the tower from here.', uses: ['g:koto-ga-dekiru', 'g:koto', 'k:見', 'v:ここ|ここ', 'v:できる|できる', 'v:見る|みる'], furigana: 'タワーはここから[見|み]ることができます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 10326084, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-koto-ga-dekiru-oyogu', kind: 'sentence', level: 'N4', jp: 'この海ではおよぐことができません。', reading: 'このうみではおよぐことができません。', en: 'You can\'t swim in this sea.', uses: ['g:koto-ga-dekiru', 'g:koto', 'k:海', 'v:海|うみ', 'v:この|この', 'v:できる|できる'], furigana: 'この[海|うみ]ではおよぐことができません。', chunks: { pre: 'この海では', move: ['およぐ', 'ことが', 'でき', 'ません'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-yasui-pen', kind: 'sentence', level: 'N4', jp: 'このペンは書きやすいです。', reading: 'このペンはかきやすいです。', en: 'This pen is easy to write with.', uses: ['g:yasui', 'k:書', 'v:書く|かく', 'v:この|この', 'v:やすい|やすい', 'v:ペン|ペン'], furigana: 'このペンは[書|か]きやすいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:206661', kind: 'sentence', level: 'N4', jp: 'その本は読みやすいよ。', reading: 'そのほんはよみやすいよ。', en: 'That book is easy to read.', uses: ['g:yasui', 'k:本', 'k:読', 'v:その|その', 'v:本|ほん', 'v:読む|よむ', 'v:やすい|やすい'], furigana: 'その[本|ほん]は[読|よ]みやすいよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 8000337, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9963851', kind: 'sentence', level: 'N4', jp: 'とても使いやすいよ。', reading: 'とてもつかいやすいよ。', en: 'It\'s very easy to use.', uses: ['g:yasui', 'k:使', 'v:使う|つかう', 'v:とても|とても', 'v:やすい|やすい'], furigana: 'とても[使|つか]いやすいよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 1571130, enAuthor: 'Spamster', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10563891', kind: 'sentence', level: 'N4', jp: 'スペイン語は習いやすいよ。', reading: 'スペインごはならいやすいよ。', en: 'Spanish is easy to learn.', uses: ['g:yasui', 'k:語', 'k:習', 'v:習う|ならう', 'v:語|ご', 'v:やすい|やすい'], furigana: 'スペイン[語|ご]は[習|なら]いやすいよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10562642, enAuthor: 'Adelpa', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nikui-kanji', kind: 'sentence', level: 'N4', jp: 'この漢字は書きにくいです。', reading: 'このかんじはかきにくいです。', en: 'This kanji is hard to write.', uses: ['g:nikui', 'k:漢', 'k:字', 'k:書', 'v:書く|かく', 'v:漢字|かんじ', 'v:この|この', 'v:にくい|にくい'], furigana: 'この[漢字|かんじ]は[書|か]きにくいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:221479', kind: 'sentence', level: 'N4', jp: 'この質問は答えにくいな。', reading: 'このしつもんはこたえにくいな。', en: 'This question is difficult to answer.', uses: ['g:nikui', 'k:質', 'k:問', 'k:答', 'v:答える|こたえる', 'v:この|この', 'v:質問|しつもん', 'v:にくい|にくい'], furigana: 'この[質問|しつ|もん]は[答|こた]えにくいな。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 58803, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8650986', kind: 'sentence', level: 'N4', jp: 'トムの書く字は読みにくい。', reading: 'トムのかくじはよみにくい。', en: 'Tom\'s handwriting is hard to read.', uses: ['g:nikui', 'g:noun-modifier', 'k:書', 'k:字', 'k:読', 'v:書く|かく', 'v:読む|よむ', 'v:字|じ', 'v:にくい|にくい'], furigana: 'トムの[書|か]く[字|じ]は[読|よ]みにくい。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 2407663, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-kata-kippu', kind: 'sentence', level: 'N4', jp: 'このきっぷの買い方を教えてください。', reading: 'このきっぷのかいかたをおしえてください。', en: 'Please tell me how to buy this ticket.', uses: ['g:kata', 'g:te-kudasai', 'g:te-form', 'k:買', 'k:方', 'k:教', 'v:教える|おしえる', 'v:買う|かう', 'v:方|かた', 'v:ください|ください', 'v:この|この', 'v:切符|きっぷ'], furigana: 'このきっぷの[買|か]い[方|かた]を[教|おし]えてください。', chunks: { pre: '', move: ['このきっぷの', '買い方を', '教えて', 'ください'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10565932', kind: 'sentence', level: 'N4', jp: 'これの使い方、知ってる？', reading: 'これのつかいかた、しってる？', en: 'Do you know how to use this?', uses: ['g:kata', 'k:使', 'k:方', 'k:知', 'v:方|かた', 'v:これ|これ', 'v:知る|しる', 'v:使う|つかう'], furigana: 'これの[使|つか]い[方|かた]、[知|し]ってる？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 3408710, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:7427294', kind: 'sentence', level: 'N4', jp: 'サラダの作り方を教えて。', reading: 'サラダのつくりかたをおしえて。', en: 'Tell me how to make a salad.', uses: ['g:kata', 'g:te-form', 'k:作', 'k:方', 'k:教', 'v:教える|おしえる', 'v:方|かた', 'v:作る|つくる', 'v:サラダ|サラダ'], furigana: 'サラダの[作|つく]り[方|かた]を[教|おし]えて。', author: 'Ninja', license: 'CC BY 2.0 FR', enId: 12805764, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:2728130', kind: 'sentence', level: 'N4', jp: '父は時間の使い方がうまい。', reading: 'ちちはじかんのつかいかたがうまい。', en: 'My father makes good use of his time.', uses: ['g:kata', 'k:父', 'k:時', 'k:間', 'k:使', 'k:方', 'v:方|かた', 'v:時間|じかん', 'v:使う|つかう', 'v:父|ちち', 'v:うまい|うまい'], furigana: '[父|ちち]は[時間|じ|かん]の[使|つか]い[方|かた]がうまい。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 1439958, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-ageru-imouto', kind: 'sentence', level: 'N4', jp: 'わたしは妹に本を読んであげました。', reading: 'わたしはいもうとにほんをよんであげました。', en: 'I read a book to my little sister.', uses: ['g:te-ageru', 'g:te-form', 'k:妹', 'k:本', 'k:読', 'v:妹|いもうと', 'v:本|ほん', 'v:読む|よむ', 'v:あげる|あげる', 'v:私|わたし'], furigana: 'わたしは[妹|いもうと]に[本|ほん]を[読|よ]んであげました。', chunks: { pre: 'わたしは', move: ['妹に', '本を', '読んで', 'あげました'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:8586214', kind: 'sentence', level: 'N4', jp: 'お茶を入れてあげるね。', reading: 'おちゃをいれてあげるね。', en: 'I\'ll make tea for you.', uses: ['g:te-ageru', 'g:te-form', 'k:茶', 'k:入', 'v:入れる|いれる', 'v:お茶|おちゃ', 'v:あげる|あげる'], furigana: 'お[茶|ちゃ]を[入|い]れてあげるね。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 64182, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1233763', kind: 'sentence', level: 'N4', jp: '駅への道を教えてあげますよ。', reading: 'えきへのみちをおしえてあげますよ。', en: 'I\'ll show you the way to the station.', uses: ['g:te-ageru', 'g:te-form', 'k:駅', 'k:道', 'k:教', 'v:駅|えき', 'v:教える|おしえる', 'v:道|みち', 'v:あげる|あげる'], furigana: '[駅|えき]への[道|みち]を[教|おし]えてあげますよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 26079, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9891143', kind: 'sentence', level: 'N4', jp: 'この本、貸してあげるね。', reading: 'このほん、かしてあげるね。', en: 'I\'ll lend you this book.', uses: ['g:te-ageru', 'g:te-form', 'k:本', 'k:貸', 'v:貸す|かす', 'v:この|この', 'v:本|ほん', 'v:あげる|あげる'], furigana: 'この[本|ほん]、[貸|か]してあげるね。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 6897855, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-kureru-keeki', kind: 'sentence', level: 'N4', jp: 'ともだちがケーキを作ってくれました。', reading: 'ともだちがケーキをつくってくれました。', en: 'My friend made a cake for me.', uses: ['g:te-kureru', 'g:te-form', 'k:作', 'v:作る|つくる', 'v:くれる|くれる', 'v:ケーキ|ケーキ', 'v:友達|ともだち'], furigana: 'ともだちがケーキを[作|つく]ってくれました。', chunks: { pre: '', move: ['ともだちが', 'ケーキを', '作って', 'くれました'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:9037336', kind: 'sentence', level: 'N4', jp: '父が本を買ってくれた。', reading: 'ちちがほんをかってくれた。', en: 'My father bought me the book.', uses: ['g:te-kureru', 'g:te-form', 'k:父', 'k:本', 'k:買', 'v:買う|かう', 'v:本|ほん', 'v:父|ちち', 'v:くれる|くれる'], furigana: '[父|ちち]が[本|ほん]を[買|か]ってくれた。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 3430738, enAuthor: 'AlanF_US', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10642319', kind: 'sentence', level: 'N4', jp: 'ドアを開けてくれる？', reading: 'ドアをあけてくれる？', en: 'Can you open the door for me, please?', uses: ['g:te-kureru', 'g:te-form', 'k:開', 'v:開ける|あける', 'v:くれる|くれる', 'v:ドア|ドア'], furigana: 'ドアを[開|あ]けてくれる？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9680688, enAuthor: 'Cabo', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:123567', kind: 'sentence', level: 'N4', jp: '道を教えてくれませんか。', reading: 'みちをおしえてくれませんか。', en: 'Could you tell me the way?', uses: ['g:te-kureru', 'g:te-form', 'k:道', 'k:教', 'v:教える|おしえる', 'v:道|みち', 'v:くれる|くれる'], furigana: '[道|みち]を[教|おし]えてくれませんか。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 280430, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-morau-shashin', kind: 'sentence', level: 'N4', jp: 'ともだちに写真をとってもらいました。', reading: 'ともだちにしゃしんをとってもらいました。', en: 'I had my friend take a photo of me.', uses: ['g:te-morau', 'g:te-form', 'k:写', 'k:真', 'v:写真|しゃしん', 'v:もらう|もらう', 'v:友達|ともだち', 'v:撮る|とる'], furigana: 'ともだちに[写真|しゃしん]をとってもらいました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10982438', kind: 'sentence', level: 'N4', jp: '母に料理を教えてもらいました。', reading: 'ははにりょうりをおしえてもらいました。', en: 'My mother taught me how to cook.', uses: ['g:te-morau', 'g:te-form', 'k:母', 'k:料', 'k:理', 'k:教', 'v:教える|おしえる', 'v:料理|りょうり', 'v:母|はは', 'v:もらう|もらう'], furigana: '[母|はは]に[料理|りょう|り]を[教|おし]えてもらいました。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12462151, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:227939', kind: 'sentence', level: 'N4', jp: 'エミはお母さんにドレスを作ってもらった。', reading: 'エミはおかあさんにドレスをつくってもらった。', en: 'Emi had her mother make a dress.', uses: ['g:te-morau', 'g:te-form', 'k:母', 'k:作', 'v:お母さん|おかあさん', 'v:作る|つくる', 'v:もらう|もらう'], furigana: 'エミはお[母|かあ]さんにドレスを[作|つく]ってもらった。', author: 'tommy__san', license: 'CC BY 2.0 FR', enId: 65292, enAuthor: 'CN', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11053931', kind: 'sentence', level: 'N4', jp: 'トムに写真を見せてもらった？', reading: 'トムにしゃしんをみせてもらった？', en: 'Did Tom show you the picture?', uses: ['g:te-morau', 'g:te-form', 'k:写', 'k:真', 'k:見', 'v:写真|しゃしん', 'v:見せる|みせる', 'v:もらう|もらう'], furigana: 'トムに[写真|しゃ|しん]を[見|み]せてもらった？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10283496, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8579832', kind: 'sentence', level: 'N4', jp: '教えてくれてありがとう。', reading: 'おしえてくれてありがとう。', en: 'Thanks for telling me.', uses: ['g:te-kurete-arigatou', 'g:te-kureru', 'g:te-form', 'k:教', 'v:教える|おしえる', 'v:くれる|くれる'], furigana: '[教|おし]えてくれてありがとう。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 3722671, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:167138', kind: 'sentence', level: 'N4', jp: '本を貸してくれてありがとう。', reading: 'ほんをかしてくれてありがとう。', en: 'Thank you for lending us the book.', uses: ['g:te-kurete-arigatou', 'g:te-kureru', 'g:te-form', 'k:本', 'k:貸', 'v:貸す|かす', 'v:本|ほん', 'v:くれる|くれる'], furigana: '[本|ほん]を[貸|か]してくれてありがとう。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 247364, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8619684', kind: 'sentence', level: 'N4', jp: '今日は来てくれてありがとう。', reading: 'きょうはきてくれてありがとう。', en: 'Thank you for coming today.', uses: ['g:te-kurete-arigatou', 'g:te-kureru', 'g:te-form', 'k:今', 'k:日', 'k:来', 'v:今日|きょう', 'v:来る|くる', 'v:くれる|くれる'], furigana: '[今日|きょう]は[来|き]てくれてありがとう。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 3096376, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-kurete-arigatou-tetsudau', kind: 'sentence', level: 'N4', jp: 'ひっこしをてつだってくれてありがとう。', reading: 'ひっこしをてつだってくれてありがとう。', en: 'Thanks for helping me move.', uses: ['g:te-kurete-arigatou', 'g:te-kureru', 'g:te-form', 'v:くれる|くれる', 'v:引っ越す|ひっこす', 'v:手伝う|てつだう'], furigana: 'ひっこしをてつだってくれてありがとう。', chunks: { pre: '', move: ['ひっこしを', 'てつだって', 'くれて', 'ありがとう'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:146797', kind: 'sentence', level: 'N4', jp: '少し待っていただけませんか。', reading: 'すこしまっていただけませんか。', en: 'Would you mind waiting a moment?', uses: ['g:te-itadakemasen-ka', 'g:te-form', 'g:potential', 'k:少', 'k:待', 'v:少し|すこし', 'v:待つ|まつ', 'v:頂く|いただく'], furigana: '[少|すこ]し[待|ま]っていただけませんか。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 267764, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:201800', kind: 'sentence', level: 'N4', jp: 'ドアを開けていただけませんか。', reading: 'ドアをあけていただけませんか。', en: 'Would you please open the door?', uses: ['g:te-itadakemasen-ka', 'g:te-form', 'g:potential', 'k:開', 'v:開ける|あける', 'v:頂く|いただく', 'v:ドア|ドア'], furigana: 'ドアを[開|あ]けていただけませんか。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 39011, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:148943', kind: 'sentence', level: 'N4', jp: '車を貸していただけませんか。', reading: 'くるまをかしていただけませんか。', en: 'Would you mind lending me your car?', uses: ['g:te-itadakemasen-ka', 'g:te-form', 'g:potential', 'k:車', 'k:貸', 'v:貸す|かす', 'v:車|くるま', 'v:頂く|いただく'], furigana: '[車|くるま]を[貸|か]していただけませんか。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 17080, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-itadakemasen-ka-michi', kind: 'sentence', level: 'N4', jp: '駅までの道を教えていただけませんか。', reading: 'えきまでのみちをおしえていただけませんか。', en: 'Could you possibly tell me the way to the station?', uses: ['g:te-itadakemasen-ka', 'g:te-form', 'g:potential', 'k:駅', 'k:道', 'k:教', 'v:駅|えき', 'v:教える|おしえる', 'v:道|みち', 'v:頂く|いただく'], furigana: '[駅|えき]までの[道|みち]を[教|おし]えていただけませんか。', chunks: { pre: '駅までの', move: ['道を', '教えて', 'いただけ', 'ませんか'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-sumimasen-osoku', kind: 'sentence', level: 'N4', jp: 'おそくなってすみません。', reading: 'おそくなってすみません。', en: 'Sorry I\'m late.', uses: ['g:te-sumimasen', 'g:te-form', 'g:naru', 'v:遅い|おそい', 'v:なる|なる'], furigana: 'おそくなってすみません。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-sumimasen-denwa', kind: 'sentence', level: 'N4', jp: 'きのうは電話しなくてすみませんでした。', reading: 'きのうはでんわしなくてすみませんでした。', en: 'Sorry I didn\'t call you yesterday.', uses: ['g:te-sumimasen', 'g:nakute', 'k:電', 'k:話', 'v:電話|でんわ', 'v:昨日|きのう'], furigana: 'きのうは[電話|でんわ]しなくてすみませんでした。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11871026', kind: 'sentence', level: 'N4', jp: '下手なフランス語ですみません。', reading: 'へたなフランスごですみません。', en: 'I\'m sorry for my poor French.', uses: ['g:te-sumimasen', 'g:te-adj-noun', 'k:下', 'k:手', 'k:語', 'v:下手|へた', 'v:語|ご'], furigana: '[下手|へた]なフランス[語|ご]ですみません。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10115358, enAuthor: 'shekitten', enLicense: 'CC0 1.0', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10193298', kind: 'sentence', level: 'N4', jp: 'たくさん質問してごめんね。', reading: 'たくさんしつもんしてごめんね。', en: 'Sorry for asking so many questions.', uses: ['g:te-sumimasen', 'g:te-form', 'k:質', 'k:問', 'v:質問|しつもん', 'v:たくさん|たくさん'], furigana: 'たくさん[質問|しつ|もん]してごめんね。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10193143, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-yokatta-daigaku', kind: 'sentence', level: 'N4', jp: 'この大学に入ってよかったです。', reading: 'このだいがくにはいってよかったです。', en: 'I\'m glad I came to this university.', uses: ['g:te-yokatta', 'g:te-form', 'k:大', 'k:学', 'k:入', 'v:この|この', 'v:大学|だいがく', 'v:入る|はいる'], furigana: 'この[大学|だいがく]に[入|はい]ってよかったです。', chunks: { pre: '', move: ['この', '大学に', '入って', 'よかった'], post: 'です。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11935865', kind: 'sentence', level: 'N4', jp: 'オーストラリアに来てよかったよ。', reading: 'オーストラリアにきてよかったよ。', en: 'I\'m glad I came to Australia.', uses: ['g:te-yokatta', 'g:te-form', 'k:来', 'v:来る|くる'], furigana: 'オーストラリアに[来|き]てよかったよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 7158918, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11924394', kind: 'sentence', level: 'N4', jp: '雨が止んでよかった。', reading: 'あめがやんでよかった。', en: 'I\'m glad that the rain has stopped.', uses: ['g:te-yokatta', 'g:te-form', 'k:雨', 'k:止', 'v:雨|あめ', 'v:止む|やむ'], furigana: '[雨|あめ]が[止|や]んでよかった。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 4097126, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11481787', kind: 'sentence', level: 'N4', jp: 'トムが家にいてよかった。', reading: 'トムがいえにいてよかった。', en: 'I\'m glad Tom is at home.', uses: ['g:te-yokatta', 'g:te-form', 'k:家', 'v:家|いえ'], furigana: 'トムが[家|いえ]にいてよかった。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 3567237, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-jita-aku', kind: 'sentence', level: 'N4', jp: 'かぜで、ドアが開きました。', reading: 'かぜで、ドアがあきました。', en: 'The door opened in the wind.', uses: ['g:jidoushi-tadoushi', 'k:開', 'v:開く|あく', 'v:風|かぜ', 'v:ドア|ドア'], furigana: 'かぜで、ドアが[開|あ]きました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:13356118', kind: 'sentence', level: 'N4', jp: 'ドアを開けました。', reading: 'ドアをあけました。', en: 'I opened the door.', uses: ['g:jidoushi-tadoushi', 'k:開', 'v:開ける|あける'], furigana: 'ドアを[開|あ]けました。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2389573, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-jita-hajimaru', kind: 'sentence', level: 'N4', jp: 'じゅぎょうは九時に始まります。', reading: 'じゅぎょうはくじにはじまります。', en: 'Class starts at nine.', uses: ['g:jidoushi-tadoushi', 'k:九', 'k:時', 'k:始', 'v:始まる|はじまる', 'v:授業|じゅぎょう'], furigana: 'じゅぎょうは[九時|くじ]に[始|はじ]まります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-jita-hajimeru', kind: 'sentence', level: 'N4', jp: '先生はじゅぎょうを始めました。', reading: 'せんせいはじゅぎょうをはじめました。', en: 'The teacher started the class.', uses: ['g:jidoushi-tadoushi', 'k:先', 'k:生', 'k:始', 'v:先生|せんせい', 'v:始める|はじめる', 'v:授業|じゅぎょう'], furigana: '[先生|せんせい]はじゅぎょうを[始|はじ]めました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11253962', kind: 'sentence', level: 'N4', jp: '電気をつけました。', reading: 'でんきをつけました。', en: 'I turned on the lights.', uses: ['g:jidoushi-tadoushi', 'k:電', 'k:気', 'v:つける|つける', 'v:電気|でんき'], furigana: '[電気|でん|き]をつけました。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 255906, enAuthor: 'Eldad', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-aru-mado', kind: 'sentence', level: 'N4', jp: 'まどが開けてあります。', reading: 'まどがあけてあります。', en: 'The window has been left open.', uses: ['g:te-aru', 'g:te-form', 'g:jidoushi-tadoushi', 'k:開', 'v:開ける|あける', 'v:窓|まど'], furigana: 'まどが[開|あ]けてあります。', chunks: { pre: '', move: ['まどが', '開けて', 'あり', 'ます'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-aru-hana', kind: 'sentence', level: 'N4', jp: 'テーブルの上に花がかざってあります。', reading: 'テーブルのうえにはながかざってあります。', en: 'Flowers have been put out on the table.', uses: ['g:te-aru', 'g:te-form', 'k:上', 'k:花', 'v:上|うえ', 'v:テーブル|テーブル', 'v:花|はな', 'v:飾る|かざる'], furigana: 'テーブルの[上|うえ]に[花|はな]がかざってあります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10901490', kind: 'sentence', level: 'N4', jp: '手紙に書いてありました。', reading: 'てがみにかいてありました。', en: 'It was written in the letter.', uses: ['g:te-aru', 'g:te-form', 'k:手', 'k:紙', 'k:書', 'v:書く|かく', 'v:手紙|てがみ'], furigana: '[手紙|て|がみ]に[書|か]いてありました。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 13459036, enAuthor: 'move0423', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10286281', kind: 'sentence', level: 'N4', jp: 'その本には何が書いてあるの？', reading: 'そのほんにはなにがかいてあるの？', en: 'What\'s written in the book?', uses: ['g:te-aru', 'g:te-form', 'k:本', 'k:何', 'k:書', 'v:書く|かく', 'v:その|その', 'v:何|なに', 'v:本|ほん'], furigana: 'その[本|ほん]には[何|なに]が[書|か]いてあるの？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 7712961, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-oku-nomimono', kind: 'sentence', level: 'N4', jp: 'パーティーの前に、飲み物を買っておきます。', reading: 'パーティーのまえに、のみものをかっておきます。', en: 'I\'ll buy drinks before the party.', uses: ['g:te-oku', 'g:te-form', 'k:前', 'k:飲', 'k:物', 'k:買', 'v:買う|かう', 'v:飲み物|のみもの', 'v:飲む|のむ', 'v:パーティー|パーティー', 'v:前|まえ', 'v:物|もの'], furigana: 'パーティーの[前|まえ]に、[飲|の]み[物|もの]を[買|か]っておきます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:173470', kind: 'sentence', level: 'N4', jp: '考えておきます。', reading: 'かんがえておきます。', en: 'I\'ll think about it.', uses: ['g:te-oku', 'g:te-form', 'k:考', 'v:考える|かんがえる'], furigana: '[考|かんが]えておきます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 31268, enAuthor: 'sacredceltic', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9930912', kind: 'sentence', level: 'N4', jp: 'この手紙を出しておいてください。', reading: 'このてがみをだしておいてください。', en: 'Please mail this letter for me.', uses: ['g:te-oku', 'g:te-form', 'g:te-kudasai', 'k:手', 'k:紙', 'k:出', 'v:ください|ください', 'v:この|この', 'v:出す|だす', 'v:手紙|てがみ'], furigana: 'この[手紙|て|がみ]を[出|だ]しておいてください。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 58643, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:79947', kind: 'sentence', level: 'N4', jp: '目を開けておくのよ。', reading: 'めをあけておくのよ。', en: 'Keep your eyes open.', uses: ['g:te-oku', 'g:te-form', 'g:jidoushi-tadoushi', 'k:目', 'k:開', 'v:開ける|あける', 'v:目|め'], furigana: '[目|め]を[開|あ]けておくのよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 323770, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-shimau-saifu', kind: 'sentence', level: 'N4', jp: 'さいふをなくしてしまいました。', reading: 'さいふをなくしてしまいました。', en: 'I\'ve gone and lost my wallet.', uses: ['g:te-shimau', 'g:te-form', 'v:財布|さいふ', 'v:無くす|なくす'], furigana: 'さいふをなくしてしまいました。', chunks: { pre: '', move: ['さいふを', 'なくして', 'しまい', 'ました'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-shimau-hon', kind: 'sentence', level: 'N4', jp: 'この本はもう読んでしまいました。', reading: 'このほんはもうよんでしまいました。', en: 'I\'ve already finished reading this book.', uses: ['g:te-shimau', 'g:te-form', 'k:本', 'k:読', 'v:この|この', 'v:本|ほん', 'v:もう|もう', 'v:読む|よむ'], furigana: 'この[本|ほん]はもう[読|よ]んでしまいました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:198118', kind: 'sentence', level: 'N4', jp: 'バスはもう行ってしまった。', reading: 'バスはもういってしまった。', en: 'The bus has already gone.', uses: ['g:te-shimau', 'g:te-form', 'k:行', 'v:もう|もう', 'v:バス|バス'], furigana: 'バスはもう[行|い]ってしまった。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 35308, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:84418', kind: 'sentence', level: 'N4', jp: '父は中国へ行ってしまった。', reading: 'ちちはちゅうごくへいってしまった。', en: 'My father has gone to China.', uses: ['g:te-shimau', 'g:te-form', 'k:父', 'k:中', 'k:国', 'k:行', 'v:父|ちち'], furigana: '[父|ちち]は[中国|ちゅう|ごく]へ[行|い]ってしまった。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 319296, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-shimau-keeki', kind: 'sentence', level: 'N4', jp: 'ケーキをぜんぶ食べちゃった。', reading: 'ケーキをぜんぶたべちゃった。', en: 'Oops, I ate the whole cake.', uses: ['g:te-shimau', 'k:食', 'v:ケーキ|ケーキ', 'v:全部|ぜんぶ', 'v:食べる|たべる'], furigana: 'ケーキをぜんぶ[食|た]べちゃった。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-miru-fuku', kind: 'sentence', level: 'N4', jp: 'この服を着てみてもいいですか。', reading: 'このふくをきてみてもいいですか。', en: 'May I try on these clothes?', uses: ['g:te-miru', 'g:te-mo-ii', 'g:te-form', 'k:服', 'k:着', 'v:いい|いい', 'v:着る|きる', 'v:この|この', 'v:服|ふく'], furigana: 'この[服|ふく]を[着|き]てみてもいいですか。', chunks: { pre: 'この服を', move: ['着て', 'みても', 'いい', 'ですか'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-miru-sensei', kind: 'sentence', level: 'N4', jp: 'あした先生に聞いてみます。', reading: 'あしたせんせいにきいてみます。', en: "I'll try asking the teacher tomorrow.", uses: ['g:te-miru', 'g:te-form', 'k:先', 'k:生', 'k:聞', 'v:明日|あした', 'v:先生|せんせい', 'v:聞く|きく'], furigana: 'あした[先生|せん|せい]に[聞|き]いてみます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:3509628', kind: 'sentence', level: 'N4', jp: 'これ着てみて。', reading: 'これきてみて。', en: 'Try this on.', uses: ['g:te-miru', 'g:te-form', 'k:着', 'v:着る|きる', 'v:これ|これ'], furigana: 'これ[着|き]てみて。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 2253805, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10032516', kind: 'sentence', level: 'N4', jp: '考えてみるよ。', reading: 'かんがえてみるよ。', en: 'Let me think about it.', uses: ['g:te-miru', 'g:te-form', 'k:考', 'v:考える|かんがえる'], furigana: '[考|かんが]えてみるよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 869514, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-iku-kasa', kind: 'sentence', level: 'N4', jp: '雨なので、かさを持っていきます。', reading: 'あめなので、かさをもっていきます。', en: 'It\'s raining, so I\'ll take an umbrella.', uses: ['g:te-iku', 'g:te-form', 'g:node', 'k:雨', 'k:持', 'v:雨|あめ', 'v:持つ|もつ', 'v:傘|かさ'], furigana: '[雨|あめ]なので、かさを[持|も]っていきます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10983063', kind: 'sentence', level: 'N4', jp: '駅まで歩いていきます。', reading: 'えきまであるいていきます。', en: 'I will walk to the train station.', uses: ['g:te-iku', 'g:te-form', 'k:駅', 'k:歩', 'v:歩く|あるく', 'v:駅|えき'], furigana: '[駅|えき]まで[歩|ある]いていきます。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 11459325, enAuthor: 'auxitt', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:152713', kind: 'sentence', level: 'N4', jp: '毎日学校へ歩いていくよ。', reading: 'まいにちがっこうへあるいていくよ。', en: 'I walk to school every day.', uses: ['g:te-iku', 'g:te-form', 'k:毎', 'k:日', 'k:学', 'k:校', 'k:歩', 'v:歩く|あるく', 'v:学校|がっこう', 'v:毎日|まいにち'], furigana: '[毎日|まい|にち][学校|がっ|こう]へ[歩|ある]いていくよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 261836, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-iku-samuku', kind: 'sentence', level: 'N4', jp: 'これから、だんだんさむくなっていきます。', reading: 'これから、だんだんさむくなっていきます。', en: 'From now on it will get colder and colder.', uses: ['g:te-iku', 'g:te-form', 'g:naru', 'v:だんだん|だんだん', 'v:これから|これから', 'v:なる|なる'], furigana: 'これから、だんだんさむくなっていきます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-kuru-ame', kind: 'sentence', level: 'N4', jp: '雨がふってきました。', reading: 'あめがふってきました。', en: 'It\'s started to rain.', uses: ['g:te-kuru', 'g:te-form', 'k:雨', 'v:雨|あめ', 'v:降る|ふる'], furigana: '[雨|あめ]がふってきました。', chunks: { pre: '', move: ['雨が', 'ふって', 'き', 'ました'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11527664', kind: 'sentence', level: 'N4', jp: '花を持ってきたよ。', reading: 'はなをもってきたよ。', en: 'I brought flowers.', uses: ['g:te-kuru', 'g:te-form', 'k:花', 'k:持', 'v:花|はな', 'v:持つ|もつ'], furigana: '[花|はな]を[持|も]ってきたよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 5858612, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-kuru-pan', kind: 'sentence', level: 'N4', jp: 'ちょっとパンを買ってくるね。', reading: 'ちょっとパンをかってくるね。', en: "I'll just pop out and buy some bread.", uses: ['g:te-kuru', 'g:te-form', 'k:買', 'v:ちょっと|ちょっと', 'v:パン|パン', 'v:買う|かう'], furigana: 'ちょっとパンを[買|か]ってくるね。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:8588370', kind: 'sentence', level: 'N4', jp: '明るくなってきた。', reading: 'あかるくなってきた。', en: 'It\'s getting light.', uses: ['g:te-kuru', 'g:te-form', 'g:naru', 'k:明', 'v:明るい|あかるい', 'v:なる|なる'], furigana: '[明|あか]るくなってきた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 2249082, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-stem-compounds-tsuzukeru', kind: 'sentence', level: 'N4', jp: '雨は一日中ふりつづけました。', reading: 'あめはいちにちじゅうふりつづけました。', en: 'It kept raining all day.', uses: ['g:stem-compounds', 'k:雨', 'k:一', 'k:日', 'k:中', 'v:雨|あめ', 'v:降る|ふる', 'v:続ける|つづける'], furigana: '[雨|あめ]は[一日中|いちにちじゅう]ふりつづけました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:4359202', kind: 'sentence', level: 'N4', jp: 'トムは読み始めました。', reading: 'トムはよみはじめました。', en: 'Tom started reading.', uses: ['g:stem-compounds', 'k:読', 'k:始', 'v:読む|よむ', 'v:始める|はじめる'], furigana: 'トムは[読|よ]み[始|はじ]めました。', author: 'verbum', license: 'CC BY 2.0 FR', enId: 2238706, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11340615', kind: 'sentence', level: 'N4', jp: '食べ終わるまで待って。', reading: 'たべおわるまでまって。', en: 'Wait till I finish eating.', uses: ['g:stem-compounds', 'g:made', 'g:te-form', 'k:食', 'k:終', 'k:待', 'v:終わる|おわる', 'v:待つ|まつ'], furigana: '[食|た]べ[終|お]わるまで[待|ま]って。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2649838, enAuthor: 'sharptoothed', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:160640', kind: 'sentence', level: 'N4', jp: '私はシチューを作り始めた。', reading: 'わたしはシチューをつくりはじめた。', en: 'I started to make stew.', uses: ['g:stem-compounds', 'k:私', 'k:作', 'k:始', 'v:作る|つくる', 'v:私|わたし', 'v:始める|はじめる'], furigana: '[私|わたし]はシチューを[作|つく]り[始|はじ]めた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 253880, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  // ── Grammar blocks 8-14 ──
  { id: 's:own:n4-ato-de-sanpo', kind: 'sentence', level: 'N4', jp: 'ばんごはんを食べた後でさんぽに行きます。', reading: 'ばんごはんをたべたあとでさんぽにいきます。', en: 'After dinner I\'ll go for a walk.', uses: ['g:ato-de', 'g:ta-form', 'k:食', 'k:後', 'k:行', 'v:後|あと', 'v:行く|いく', 'v:食べる|たべる', 'v:晩御飯|ばんごはん', 'v:散歩|さんぽ'], furigana: 'ばんごはんを[食|た]べた[後|あと]でさんぽに[行|い]きます。', chunks: { pre: 'ばんごはんを', move: ['食べた', '後で', 'さんぽに', '行きます'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-ato-de-jugyou', kind: 'sentence', level: 'N4', jp: 'じゅぎょうの後で、先生に聞きました。', reading: 'じゅぎょうのあとで、せんせいにききました。', en: 'After class, I asked the teacher.', uses: ['g:ato-de', 'k:後', 'k:先', 'k:生', 'k:聞', 'v:後|あと', 'v:聞く|きく', 'v:先生|せんせい', 'v:授業|じゅぎょう'], furigana: 'じゅぎょうの[後|あと]で、[先生|せんせい]に[聞|き]きました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10914867', kind: 'sentence', level: 'N4', jp: 'また後で来ます。', reading: 'またあとできます。', en: 'I\'ll come later.', uses: ['g:ato-de', 'k:後', 'k:来', 'v:後|あと', 'v:来る|くる'], furigana: 'また[後|あと]で[来|き]ます。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 5858237, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:3024537', kind: 'sentence', level: 'N4', jp: 'また後で電話するね。', reading: 'またあとででんわするね。', en: 'I\'ll call again later.', uses: ['g:ato-de', 'k:後', 'k:電', 'k:話', 'v:後|あと', 'v:電話|でんわ', 'v:する|する'], furigana: 'また[後|あと]で[電話|でん|わ]するね。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 32616, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-made-ni-shukudai', kind: 'sentence', level: 'N4', jp: 'しゅくだいは金曜日までに出してください。', reading: 'しゅくだいはきんようびまでにだしてください。', en: 'Please hand in the homework by Friday.', uses: ['g:made-ni', 'g:te-kudasai', 'g:te-form', 'k:金', 'k:曜', 'k:日', 'k:出', 'v:金曜日|きんようび', 'v:ください|ください', 'v:出す|だす', 'v:宿題|しゅくだい'], furigana: 'しゅくだいは[金曜日|きんようび]までに[出|だ]してください。', chunks: { pre: 'しゅくだいは', move: ['金曜日', 'までに', '出して', 'ください'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-made-ni-kaeru', kind: 'sentence', level: 'N4', jp: '五時まで仕事をして、六時までに家に帰ります。', reading: 'ごじまでしごとをして、ろくじまでにいえにかえります。', en: 'I work until five and get home by six.', uses: ['g:made-ni', 'g:made', 'g:te-form', 'k:五', 'k:時', 'k:仕', 'k:事', 'k:六', 'k:家', 'k:帰', 'v:家|いえ', 'v:帰る|かえる', 'v:仕事|しごと', 'v:する|する'], furigana: '[五時|ごじ]まで[仕事|しごと]をして、[六時|ろくじ]までに[家|いえ]に[帰|かえ]ります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:232004', kind: 'sentence', level: 'N4', jp: '三時までには着きますよ。', reading: 'さんじまでにはつきますよ。', en: 'You\'ll get there by three o\'clock.', uses: ['g:made-ni', 'k:三', 'k:時', 'k:着', 'v:着く|つく'], furigana: '[三|さん][時|じ]までには[着|つ]きますよ。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 69372, enAuthor: 'CN', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:175607', kind: 'sentence', level: 'N4', jp: '月曜までにこの仕事を終えてください。', reading: 'げつようまでにこのしごとをおえてください。', en: 'Please get this work finished by Monday.', uses: ['g:made-ni', 'g:te-kudasai', 'g:te-form', 'k:月', 'k:曜', 'k:仕', 'k:事', 'k:終', 'v:ください|ください', 'v:この|この', 'v:仕事|しごと'], furigana: '[月曜|げつ|よう]までにこの[仕事|し|ごと]を[終|お]えてください。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 238858, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-goro-neru', kind: 'sentence', level: 'N4', jp: 'まいばん十一時ごろねます。', reading: 'まいばんじゅういちじごろねます。', en: 'I go to bed around eleven every night.', uses: ['g:goro', 'k:十', 'k:一', 'k:時', 'v:毎晩|まいばん', 'v:寝る|ねる', 'v:ごろ|ごろ'], furigana: 'まいばん[十一時|じゅういちじ]ごろねます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:187461', kind: 'sentence', level: 'N4', jp: '何時ごろ？', reading: 'なんじごろ？', en: 'About what time?', uses: ['g:goro', 'k:何', 'k:時', 'v:ごろ|ごろ'], furigana: '[何|なん][時|じ]ごろ？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 24599, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11241491', kind: 'sentence', level: 'N4', jp: '六時ごろ来るって言ってたよ。', reading: 'ろくじごろくるっていってたよ。', en: 'She told me she would be here about six.', uses: ['g:goro', 'g:tte', 'k:六', 'k:時', 'k:来', 'k:言', 'v:言う|いう', 'v:来る|くる', 'v:ごろ|ごろ'], furigana: '[六|ろく][時|じ]ごろ[来|く]るって[言|い]ってたよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 309900, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-goro-kaeru', kind: 'sentence', level: 'N4', jp: 'あしたは何時ごろ帰りますか。', reading: 'あしたはなんじごろかえりますか。', en: 'About what time will you be home tomorrow?', uses: ['g:goro', 'k:何', 'k:時', 'k:帰', 'v:明日|あした', 'v:何|なん', 'v:帰る|かえる', 'v:ごろ|ごろ'], furigana: 'あしたは[何|なん][時|じ]ごろ[帰|かえ]りますか。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-ni-frequency-puuru', kind: 'sentence', level: 'N4', jp: '週に二度プールでおよぎます。', reading: 'しゅうににどプールでおよぎます。', en: 'I swim in the pool twice a week.', uses: ['g:ni-frequency', 'k:週', 'k:二', 'k:度', 'v:プール|プール', 'v:泳ぐ|およぐ'], furigana: '[週|しゅう]に[二度|にど]プールでおよぎます。', chunks: { pre: '', move: ['週に', '二度', 'プールで', 'およぎます'], post: '。', star: [3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:1174310', kind: 'sentence', level: 'N4', jp: '月に一度、母に手紙を書きます。', reading: 'つきにいちど、ははにてがみをかきます。', en: 'I write to my mother once a month.', uses: ['g:ni-frequency', 'k:月', 'k:一', 'k:度', 'k:母', 'k:手', 'k:紙', 'k:書', 'v:書く|かく', 'v:手紙|てがみ', 'v:母|はは', 'v:一度|いちど', 'v:月|つき'], furigana: '[月|つき]に[一|いち][度|ど]、[母|はは]に[手紙|て|がみ]を[書|か]きます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 320584, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1085893', kind: 'sentence', level: 'N4', jp: '週に一度ここに集まりましょう。', reading: 'しゅうにいちどここにあつまりましょう。', en: 'Let\'s get together here once a week.', uses: ['g:ni-frequency', 'g:mashou', 'k:週', 'k:一', 'k:度', 'k:集', 'v:ここ|ここ', 'v:一度|いちど', 'v:集まる|あつまる'], furigana: '[週|しゅう]に[一度|いち|ど]ここに[集|あつ]まりましょう。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 73139, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9200773', kind: 'sentence', level: 'N4', jp: '今もね、週に一度トムとテニスしてるんだ。', reading: 'いまもね、しゅうにいちどトムとテニスしてるんだ。', en: 'I still play tennis with Tom once a week.', uses: ['g:ni-frequency', 'k:今', 'k:週', 'k:一', 'k:度', 'v:今|いま', 'v:一度|いちど', 'v:テニス|テニス', 'v:する|する'], furigana: '[今|いま]もね、[週|しゅう]に[一|いち][度|ど]トムとテニスしてるんだ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9200666, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nagara-ongaku', kind: 'sentence', level: 'N4', jp: '音楽を聞きながら勉強します。', reading: 'おんがくをききながらべんきょうします。', en: 'I study while listening to music.', uses: ['g:nagara', 'k:音', 'k:楽', 'k:聞', 'k:勉', 'k:強', 'v:音楽|おんがく', 'v:聞く|きく'], furigana: '[音楽|おんがく]を[聞|き]きながら[勉強|べんきょう]します。', chunks: { pre: '', move: ['音楽を', '聞き', 'ながら', '勉強'], post: 'します。', star: [3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11765971', kind: 'sentence', level: 'N4', jp: 'トムは夕飯を食べながらテレビを見ていた。', reading: 'トムはゆうはんをたべながらテレビをみていた。', en: 'Tom watched TV while he ate dinner.', uses: ['g:nagara', 'g:te-ita', 'g:te-form', 'k:夕', 'k:飯', 'k:食', 'k:見', 'v:食べる|たべる', 'v:テレビ|テレビ', 'v:見る|みる', 'v:夕飯|ゆうはん'], furigana: 'トムは[夕飯|ゆう|はん]を[食|た]べながらテレビを[見|み]ていた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 5386425, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:81619', kind: 'sentence', level: 'N4', jp: '本を読みながら食事をしてはいけません。', reading: 'ほんをよみながらしょくじをしてはいけません。', en: 'Don\'t eat while reading.', uses: ['g:nagara', 'g:te-wa-ikemasen', 'g:te-form', 'k:本', 'k:読', 'k:食', 'k:事', 'v:本|ほん', 'v:読む|よむ', 'v:食事|しょくじ'], furigana: '[本|ほん]を[読|よ]みながら[食事|しょく|じ]をしてはいけません。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 322097, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:166551', kind: 'sentence', level: 'N4', jp: '私たちはコーヒーを飲みながらおしゃべりをした。', reading: 'わたしたちはコーヒーをのみながらおしゃべりをした。', en: 'We had a chat over a cup of coffee.', uses: ['g:nagara', 'k:私', 'k:飲', 'v:コーヒー|コーヒー', 'v:飲む|のむ', 'v:私|わたし'], furigana: '[私|わたし]たちはコーヒーを[飲|の]みながらおしゃべりをした。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 247951, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-aida-ni-haha', kind: 'sentence', level: 'N4', jp: '母がねている間にばんごはんを作りました。', reading: 'ははがねているあいだにばんごはんをつくりました。', en: 'While my mother was sleeping, I made dinner.', uses: ['g:te-iru-aida-ni', 'g:te-iru', 'g:te-form', 'k:母', 'k:間', 'k:作', 'v:作る|つくる', 'v:母|はは', 'v:間|あいだ', 'v:寝る|ねる', 'v:晩御飯|ばんごはん'], furigana: '[母|はは]がねている[間|あいだ]にばんごはんを[作|つく]りました。', chunks: { pre: '母が', move: ['ねている', '間に', 'ばんごはんを', '作りました'], post: '。', star: [3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-aida-ni-nihon', kind: 'sentence', level: 'N4', jp: '日本にいる間に、いろいろなところへ行きたいです。', reading: 'にほんにいるあいだに、いろいろなところへいきたいです。', en: 'While I\'m in Japan, I want to go to lots of places.', uses: ['g:te-iru-aida-ni', 'g:tai', 'k:日', 'k:本', 'k:間', 'k:行', 'v:行く|いく', 'v:いろいろ|いろいろ', 'v:間|あいだ', 'v:所|ところ'], furigana: '[日本|にほん]にいる[間|あいだ]に、いろいろなところへ[行|い]きたいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:8720976', kind: 'sentence', level: 'N4', jp: '夏休みの間にそれをした。', reading: 'なつやすみのあいだにそれをした。', en: 'I did that during the summer holidays.', uses: ['g:te-iru-aida-ni', 'k:夏', 'k:休', 'k:間', 'v:それ|それ', 'v:夏休み|なつやすみ', 'v:間|あいだ'], furigana: '[夏休|なつ|やす]みの[間|あいだ]にそれをした。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 6803613, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:338061', kind: 'sentence', level: 'N4', jp: '休みの間に東京へ一週間行きます。', reading: 'やすみのあいだにとうきょうへいっしゅうかんいきます。', en: 'For the holidays, I\'m going to Tokyo for a week.', uses: ['g:te-iru-aida-ni', 'k:休', 'k:間', 'k:東', 'k:京', 'k:一', 'k:週', 'k:行', 'v:行く|いく', 'v:休み|やすみ', 'v:週間|しゅうかん', 'v:間|あいだ'], furigana: '[休|やす]みの[間|あいだ]に[東京|とう|きょう]へ[一|いっ][週間|しゅう|かん][行|い]きます。', author: 'shiboy', license: 'CC BY 2.0 FR', enId: 535044, enAuthor: 'blay_paul', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-tokoro-deru', kind: 'sentence', level: 'N4', jp: 'ちょうど今、家を出るところです。', reading: 'ちょうどいま、いえをでるところです。', en: 'I\'m just about to leave the house.', uses: ['g:tokoro-da', 'k:今', 'k:家', 'k:出', 'v:家|いえ', 'v:今|いま', 'v:ちょうど|ちょうど', 'v:出る|でる'], furigana: 'ちょうど[今|いま]、[家|いえ]を[出|で]るところです。', chunks: { pre: 'ちょうど今、', move: ['家を', '出る', 'ところ', 'です'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:157026', kind: 'sentence', level: 'N4', jp: '手紙を書いているところです。', reading: 'てがみをかいているところです。', en: 'I am writing a letter.', uses: ['g:tokoro-da', 'g:te-iru', 'g:te-form', 'k:手', 'k:紙', 'k:書', 'v:書く|かく', 'v:手紙|てがみ'], furigana: '[手紙|て|がみ]を[書|か]いているところです。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 257508, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:172862', kind: 'sentence', level: 'N4', jp: '今ここに来たところだ。', reading: 'いまここにきたところだ。', en: 'I have just come here.', uses: ['g:tokoro-da', 'g:ta-form', 'k:今', 'k:来', 'v:今|いま', 'v:来る|くる', 'v:ここ|ここ'], furigana: '[今|いま]ここに[来|き]たところだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 241611, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:203585', kind: 'sentence', level: 'N4', jp: 'たった今帰ったところだよ。', reading: 'たったいまかえったところだよ。', en: 'I\'ve just come back.', uses: ['g:tokoro-da', 'g:ta-form', 'k:今', 'k:帰', 'v:帰る|かえる'], furigana: 'たった[今|いま][帰|かえ]ったところだよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 40823, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-to-botan', kind: 'sentence', level: 'N4', jp: 'このボタンをおすと、ドアが開きます。', reading: 'このボタンをおすと、ドアがあきます。', en: 'When you press this button, the door opens.', uses: ['g:to-conditional', 'k:開', 'v:開く|あく', 'v:この|この', 'v:ボタン|ボタン', 'v:押す|おす', 'v:ドア|ドア'], furigana: 'このボタンをおすと、ドアが[開|あ]きます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-to-michi', kind: 'sentence', level: 'N4', jp: '右にまがると、駅が見えます。', reading: 'みぎにまがると、えきがみえます。', en: 'Turn right and you\'ll see the station.', uses: ['g:to-conditional', 'k:右', 'k:駅', 'k:見', 'v:駅|えき', 'v:右|みぎ', 'v:見える|みえる', 'v:曲がる|まがる'], furigana: '[右|みぎ]にまがると、[駅|えき]が[見|み]えます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11038976', kind: 'sentence', level: 'N4', jp: '夏が終わると、秋が来ます。', reading: 'なつがおわると、あきがきます。', en: 'Summer ends and autumn comes.', uses: ['g:to-conditional', 'k:夏', 'k:終', 'k:秋', 'k:来', 'v:秋|あき', 'v:終わる|おわる', 'v:来る|くる', 'v:夏|なつ'], furigana: '[夏|なつ]が[終|お]わると、[秋|あき]が[来|き]ます。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 13732490, enAuthor: 'terrywallwork', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11021414', kind: 'sentence', level: 'N4', jp: 'ここから少し西へ行くと、海があります。', reading: 'ここからすこしにしへいくと、うみがあります。', en: 'If you go a little west from here you\'ll find the sea.', uses: ['g:to-conditional', 'g:ga-arimasu', 'k:少', 'k:西', 'k:行', 'k:海', 'v:行く|いく', 'v:海|うみ', 'v:ここ|ここ', 'v:少し|すこし', 'v:西|にし'], furigana: 'ここから[少|すこ]し[西|にし]へ[行|い]くと、[海|うみ]があります。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12272799, enAuthor: 'Morg', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10932044', kind: 'sentence', level: 'N4', jp: '父は毎朝起きると、新聞を読みます。', reading: 'ちちはまいあさおきると、しんぶんをよみます。', en: 'When my father gets up every morning, he reads the newspaper.', uses: ['g:to-conditional', 'k:父', 'k:毎', 'k:朝', 'k:起', 'k:新', 'k:聞', 'k:読', 'v:起きる|おきる', 'v:新聞|しんぶん', 'v:毎朝|まいあさ', 'v:読む|よむ', 'v:父|ちち'], furigana: '[父|ちち]は[毎朝|まい|あさ][起|お]きると、[新聞|しん|ぶん]を[読|よ]みます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 11931258, enAuthor: 'end', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-to-ii-hareru', kind: 'sentence', level: 'N4', jp: 'あした、はれるといいですね。', reading: 'あした、はれるといいですね。', en: 'I hope it\'s sunny tomorrow.', uses: ['g:to-ii', 'v:いい|いい', 'v:明日|あした', 'v:晴れる|はれる'], furigana: 'あした、はれるといいですね。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:9809478', kind: 'sentence', level: 'N4', jp: 'トムが早く元気になるといいね。', reading: 'トムがはやくげんきになるといいね。', en: 'I hope Tom gets well soon.', uses: ['g:to-ii', 'g:naru', 'k:早', 'k:元', 'k:気', 'v:いい|いい', 'v:元気|げんき', 'v:早い|はやい', 'v:なる|なる'], furigana: 'トムが[早|はや]く[元気|げん|き]になるといいね。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2360909, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10365237', kind: 'sentence', level: 'N4', jp: 'また会えるといいですね。', reading: 'またあえるといいですね。', en: 'We hope to see you again.', uses: ['g:to-ii', 'g:potential', 'k:会', 'v:会う|あう', 'v:いい|いい', 'v:また|また'], furigana: 'また[会|あ]えるといいですね。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 31504, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10989493', kind: 'sentence', level: 'N4', jp: '明日は、いい日だといいな。', reading: 'あしたは、いいひだといいな。', en: 'I hope tomorrow will be a good day.', uses: ['g:to-ii', 'k:明', 'k:日', 'v:明日|あした', 'v:いい|いい', 'v:日|ひ'], furigana: '[明日|あした]は、いい[日|ひ]だといいな。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10989365, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11052418', kind: 'sentence', level: 'N4', jp: 'ここにカンマを入れるといいですよ。', reading: 'ここにカンマをいれるといいですよ。', en: 'I suggest putting a comma here.', uses: ['g:to-ii', 'k:入', 'v:いい|いい', 'v:入れる|いれる', 'v:ここ|ここ'], furigana: 'ここにカンマを[入|い]れるといいですよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2098209, enAuthor: 'AlanF_US', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-tara-nihon', kind: 'sentence', level: 'N4', jp: '日本へ行ったら、すしを食べたいです。', reading: 'にほんへいったら、すしをたべたいです。', en: 'When I go to Japan, I want to eat sushi.', uses: ['g:tara', 'g:ta-form', 'g:tai', 'k:日', 'k:本', 'k:行', 'k:食', 'v:食べる|たべる'], furigana: '[日本|にほん]へ[行|い]ったら、すしを[食|た]べたいです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-tara-eki', kind: 'sentence', level: 'N4', jp: '駅に着いたら電話してください。', reading: 'えきについたらでんわしてください。', en: 'Please call me when you get to the station.', uses: ['g:tara', 'g:ta-form', 'g:te-kudasai', 'g:te-form', 'k:駅', 'k:着', 'k:電', 'k:話', 'v:駅|えき', 'v:ください|ください', 'v:着く|つく', 'v:電話|でんわ', 'v:する|する'], furigana: '[駅|えき]に[着|つ]いたら[電話|でんわ]してください。', chunks: { pre: '', move: ['駅に', '着いたら', '電話して', 'ください'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10637887', kind: 'sentence', level: 'N4', jp: '時間があったら、行くよ。', reading: 'じかんがあったら、いくよ。', en: 'If I have time, I\'ll come.', uses: ['g:tara', 'g:ga-arimasu', 'k:時', 'k:間', 'k:行', 'v:行く|いく', 'v:時間|じかん'], furigana: '[時間|じ|かん]があったら、[行|い]くよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9862063, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11284358', kind: 'sentence', level: 'N4', jp: '終わったら、電話して。', reading: 'おわったら、でんわして。', en: 'Phone me when you\'ve finished.', uses: ['g:tara', 'k:終', 'k:電', 'k:話', 'v:終わる|おわる', 'v:電話|でんわ', 'v:する|する'], furigana: '[終|お]わったら、[電話|でん|わ]して。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10531324, enAuthor: 'sundown', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:889751', kind: 'sentence', level: 'N4', jp: '大きくなったら、何になりたい？', reading: 'おおきくなったら、なんになりたい？', en: 'What do you want to be when you grow up?', uses: ['g:tara', 'g:naru', 'g:tai', 'k:大', 'k:何', 'v:大きい|おおきい', 'v:何|なん', 'v:なる|なる'], furigana: '[大|おお]きくなったら、[何|なん]になりたい？', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 15915, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-tara-dou-kusuri', kind: 'sentence', level: 'N4', jp: 'くすりを飲んだらどうですか。', reading: 'くすりをのんだらどうですか。', en: 'Why don\'t you take some medicine?', uses: ['g:tara-dou', 'g:ta-form', 'k:飲', 'v:飲む|のむ', 'v:どう|どう', 'v:薬|くすり'], furigana: 'くすりを[飲|の]んだらどうですか。', chunks: { pre: '', move: ['くすりを', '飲んだら', 'どう', 'ですか'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:146815', kind: 'sentence', level: 'N4', jp: '少し休んだらどうですか。', reading: 'すこしやすんだらどうですか。', en: 'Why don\'t you rest a bit?', uses: ['g:tara-dou', 'k:少', 'k:休', 'v:少し|すこし', 'v:休む|やすむ', 'v:どう|どう'], furigana: '[少|すこ]し[休|やす]んだらどうですか。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 40026, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:194237', kind: 'sentence', level: 'N4', jp: 'もう帰ったらどうですか。', reading: 'もうかえったらどうですか。', en: 'You may as well go home now.', uses: ['g:tara-dou', 'g:mou', 'k:帰', 'v:帰る|かえる', 'v:もう|もう', 'v:どう|どう'], furigana: 'もう[帰|かえ]ったらどうですか。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 31410, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:189329', kind: 'sentence', level: 'N4', jp: '映画に行ったらどうですか。', reading: 'えいがにいったらどうですか。', en: 'Why not go to the movies?', uses: ['g:tara-dou', 'k:映', 'k:画', 'k:行', 'v:映画|えいが', 'v:どう|どう'], furigana: '[映画|えい|が]に[行|い]ったらどうですか。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 26477, enAuthor: 'papabear', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9966058', kind: 'sentence', level: 'N4', jp: '何か言ったらどう？', reading: 'なにかいったらどう？', en: 'Why don\'t you say something?', uses: ['g:tara-dou', 'k:何', 'k:言', 'v:言う|いう', 'v:何|なに', 'v:どう|どう'], furigana: '[何|なに]か[言|い]ったらどう？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 5493773, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-baai-ame', kind: 'sentence', level: 'N4', jp: '雨のばあいは、うちで食べます。', reading: 'あめのばあいは、うちでたべます。', en: 'If it rains, we\'ll eat at home.', uses: ['g:baai-wa', 'k:雨', 'k:食', 'v:雨|あめ', 'v:食べる|たべる', 'v:場合|ばあい', 'v:うち|うち'], furigana: '[雨|あめ]のばあいは、うちで[食|た]べます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-baai-jishin', kind: 'sentence', level: 'N4', jp: 'じしんのばあいは、エレベーターを使わないでください。', reading: 'じしんのばあいは、エレベーターをつかわないでください。', en: 'In case of an earthquake, don\'t use the elevator.', uses: ['g:baai-wa', 'g:nai-de-kudasai', 'g:nai-form', 'k:使', 'v:エレベーター|エレベーター', 'v:ください|ください', 'v:使う|つかう', 'v:場合|ばあい', 'v:地震|じしん'], furigana: 'じしんのばあいは、エレベーターを[使|つか]わないでください。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-baai-yasumu', kind: 'sentence', level: 'N4', jp: '学校を休むばあいは、先生にれんらくしてください。', reading: 'がっこうをやすむばあいは、せんせいにれんらくしてください。', en: 'If you\'re going to miss school, let the teacher know.', uses: ['g:baai-wa', 'g:te-kudasai', 'g:te-form', 'k:学', 'k:校', 'k:休', 'k:先', 'k:生', 'v:学校|がっこう', 'v:ください|ください', 'v:先生|せんせい', 'v:休む|やすむ', 'v:場合|ばあい', 'v:連絡|れんらく', 'v:する|する'], furigana: '[学校|がっこう]を[休|やす]むばあいは、[先生|せんせい]にれんらくしてください。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-baai-wakaranai', kind: 'sentence', level: 'N4', jp: 'わからないばあいは聞いてください。', reading: 'わからないばあいはきいてください。', en: 'If you don\'t understand, please ask.', uses: ['g:baai-wa', 'g:nai-form', 'g:te-kudasai', 'g:te-form', 'k:聞', 'v:聞く|きく', 'v:ください|ください', 'v:場合|ばあい', 'v:分かる|わかる'], furigana: 'わからないばあいは[聞|き]いてください。', chunks: { pre: '', move: ['わからない', 'ばあいは', '聞いて', 'ください'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-ba-kusuri', kind: 'sentence', level: 'N4', jp: 'このくすりを飲めばよくなりますよ。', reading: 'このくすりをのめばよくなりますよ。', en: 'If you take this medicine, you\'ll get better.', uses: ['g:ba', 'g:naru', 'k:飲', 'v:この|この', 'v:飲む|のむ', 'v:薬|くすり', 'v:なる|なる', 'v:よい|よい'], furigana: 'このくすりを[飲|の]めばよくなりますよ。', chunks: { pre: 'この', move: ['くすりを', '飲めば', 'よく', 'なります'], post: 'よ。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10982400', kind: 'sentence', level: 'N4', jp: '安ければ、買います。', reading: 'やすければ、かいます。', en: 'If it\'s cheap, I\'ll buy it.', uses: ['g:ba', 'k:安', 'k:買', 'v:買う|かう', 'v:安い|やすい'], furigana: '[安|やす]ければ、[買|か]います。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12306558, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10637878', kind: 'sentence', level: 'N4', jp: '時間があれば、来るよ。', reading: 'じかんがあれば、くるよ。', en: 'If he has time, he will come.', uses: ['g:ba', 'g:ga-arimasu', 'k:時', 'k:間', 'k:来', 'v:来る|くる', 'v:時間|じかん'], furigana: '[時間|じ|かん]があれば、[来|く]るよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 30998, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8856423', kind: 'sentence', level: 'N4', jp: '毎日日本語を勉強すれば、もっと上手になりますよ。', reading: 'まいにちにほんごをべんきょうすれば、もっとじょうずになりますよ。', en: 'If you study Japanese every day, you\'ll get better at it.', uses: ['g:ba', 'g:naru', 'k:毎', 'k:日', 'k:本', 'k:語', 'k:勉', 'k:強', 'k:上', 'k:手', 'v:上手|じょうず', 'v:毎日|まいにち', 'v:もっと|もっと', 'v:なる|なる'], furigana: '[毎日|まい|にち][日本語|に|ほん|ご]を[勉強|べん|きょう]すれば、もっと[上手|じょう|ず]になりますよ。', author: 'mochico', license: 'CC BY 2.0 FR', enId: 10765359, enAuthor: 'end', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10083290', kind: 'sentence', level: 'N4', jp: '質問があれば、聞いてください。', reading: 'しつもんがあれば、きいてください。', en: 'If you have any questions, just ask.', uses: ['g:ba', 'g:ga-arimasu', 'g:te-kudasai', 'g:te-form', 'k:質', 'k:問', 'k:聞', 'v:聞く|きく', 'v:ください|ください', 'v:質問|しつもん'], furigana: '[質問|しつ|もん]があれば、[聞|き]いてください。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 3142827, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-ba-yokatta-benkyou', kind: 'sentence', level: 'N4', jp: 'もっと勉強すればよかったです。', reading: 'もっとべんきょうすればよかったです。', en: 'I should have studied more.', uses: ['g:ba-yokatta', 'g:ba', 'k:勉', 'k:強', 'v:もっと|もっと'], furigana: 'もっと[勉強|べんきょう]すればよかったです。', chunks: { pre: '', move: ['もっと', '勉強', 'すれば', 'よかった'], post: 'です。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:226211', kind: 'sentence', level: 'N4', jp: 'カメラを持ってくればよかった。', reading: 'カメラをもってくればよかった。', en: 'I should\'ve brought my camera.', uses: ['g:ba-yokatta', 'g:ba', 'g:te-kuru', 'g:te-form', 'k:持', 'v:カメラ|カメラ', 'v:持つ|もつ'], furigana: 'カメラを[持|も]ってくればよかった。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 63551, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:193252', kind: 'sentence', level: 'N4', jp: 'もっと早くに出発すればよかった。', reading: 'もっとはやくにしゅっぱつすればよかった。', en: 'I should have left earlier.', uses: ['g:ba-yokatta', 'g:ba', 'k:早', 'k:出', 'k:発', 'v:早い|はやい', 'v:もっと|もっと'], furigana: 'もっと[早|はや]くに[出発|しゅっ|ぱつ]すればよかった。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 30410, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11436390', kind: 'sentence', level: 'N4', jp: 'もっと早くトムに話せばよかったよ。', reading: 'もっとはやくトムにはなせばよかったよ。', en: 'I should\'ve told Tom earlier.', uses: ['g:ba-yokatta', 'g:ba', 'k:早', 'k:話', 'v:話す|はなす', 'v:早い|はやい', 'v:もっと|もっと'], furigana: 'もっと[早|はや]くトムに[話|はな]せばよかったよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 2406458, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:2280872', kind: 'sentence', level: 'N4', jp: 'あんなに早く起きなければよかった。', reading: 'あんなにはやくおきなければよかった。', en: 'I shouldn\'t have gotten up so early.', uses: ['g:ba-yokatta', 'g:ba', 'k:早', 'k:起', 'v:起きる|おきる', 'v:早い|はやい', 'v:あんな|あんな'], furigana: 'あんなに[早|はや]く[起|お]きなければよかった。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 953601, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nara-sushi', kind: 'sentence', level: 'N4', jp: 'すしなら、あの店がいいですよ。', reading: 'すしなら、あのみせがいいですよ。', en: 'If it\'s sushi you want, that place is good.', uses: ['g:nara', 'k:店', 'v:あの|あの', 'v:いい|いい', 'v:店|みせ'], furigana: 'すしなら、あの[店|みせ]がいいですよ。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:80338', kind: 'sentence', level: 'N4', jp: '明日雨なら、家にいます。', reading: 'あしたあめなら、いえにいます。', en: 'I\'ll stay home if it rains tomorrow.', uses: ['g:nara', 'k:明', 'k:日', 'k:雨', 'k:家', 'v:明日|あした', 'v:家|いえ', 'v:居る|いる'], furigana: '[明日|あした][雨|あめ]なら、[家|いえ]にいます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 323379, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10570281', kind: 'sentence', level: 'N4', jp: 'この映画なら、もう見たよ。', reading: 'このえいがなら、もうみたよ。', en: 'We\'ve already seen this movie.', uses: ['g:nara', 'g:mou', 'g:ta-form', 'k:映', 'k:画', 'k:見', 'v:映画|えいが', 'v:この|この', 'v:見る|みる', 'v:もう|もう'], furigana: 'この[映画|えい|が]なら、もう[見|み]たよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 3310094, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9440712', kind: 'sentence', level: 'N4', jp: '旅行するなら、どこに行ってみたいですか？', reading: 'りょこうするなら、どこにいってみたいですか？', en: 'If you were to travel, where would you want to try and go?', uses: ['g:nara', 'g:te-miru', 'g:tai', 'g:te-form', 'k:旅', 'k:行', 'v:どこ|どこ', 'v:旅行|りょこう', 'v:する|する'], furigana: '[旅行|りょ|こう]するなら、どこに[行|い]ってみたいですか？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10288695, enAuthor: 'terrywallwork', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:12365439', kind: 'sentence', level: 'N4', jp: 'あなたが行くんなら、私も行きます。', reading: 'あなたがいくんなら、わたしもいきます。', en: 'If you go, I\'ll go, too.', uses: ['g:nara', 'k:行', 'k:私', 'v:あなた|あなた', 'v:行く|いく', 'v:私|わたし'], furigana: 'あなたが[行|い]くんなら、[私|わたし]も[行|い]きます。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 3524462, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-te-mo-ame', kind: 'sentence', level: 'N4', jp: '雨がふっても、行きます。', reading: 'あめがふっても、いきます。', en: 'I\'ll go even if it rains.', uses: ['g:te-mo', 'g:te-form', 'k:雨', 'k:行', 'v:雨|あめ', 'v:行く|いく', 'v:降る|ふる'], furigana: '[雨|あめ]がふっても、[行|い]きます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-te-mo-takai', kind: 'sentence', level: 'N4', jp: 'この本は高くても買いたいです。', reading: 'このほんはたかくてもかいたいです。', en: 'I want to buy this book even if it is expensive.', uses: ['g:te-mo', 'g:tai', 'k:本', 'k:高', 'k:買', 'v:買う|かう', 'v:この|この', 'v:高い|たかい', 'v:本|ほん'], furigana: 'この[本|ほん]は[高|たか]くても[買|か]いたいです。', chunks: { pre: 'この', move: ['本は', '高くても', '買い', 'たい'], post: 'です。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:6015', kind: 'sentence', level: 'N4', jp: 'いくら考えても、わかりません。', reading: 'いくらかんがえても、わかりません。', en: 'No matter how much I consider it I do not understand.', uses: ['g:te-mo', 'g:te-form', 'k:考', 'v:いくら|いくら', 'v:考える|かんがえる', 'v:分かる|わかる'], furigana: 'いくら[考|かんが]えても、わかりません。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 119888, enAuthor: 'fcbond', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10119936', kind: 'sentence', level: 'N4', jp: 'どんなことがあっても行くよ。', reading: 'どんなことがあってもいくよ。', en: 'I\'ll go no matter what.', uses: ['g:te-mo', 'g:te-form', 'k:行', 'v:行く|いく', 'v:どんな|どんな', 'v:事|こと'], furigana: 'どんなことがあっても[行|い]くよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 25155, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1488024', kind: 'sentence', level: 'N4', jp: 'トムは何があっても行くつもりだ。', reading: 'トムはなにがあってもいくつもりだ。', en: 'Tom intends to go, rain or shine.', uses: ['g:te-mo', 'g:tsumori', 'g:te-form', 'k:何', 'k:行', 'v:行く|いく', 'v:何|なに', 'v:つもり|つもり'], furigana: 'トムは[何|なに]があっても[行|い]くつもりだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1093517, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-noni-nichiyoubi', kind: 'sentence', level: 'N4', jp: '日曜日なのに、会社に行きました。', reading: 'にちようびなのに、かいしゃにいきました。', en: 'Even though it was Sunday, I went to the office.', uses: ['g:noni', 'k:日', 'k:曜', 'k:会', 'k:社', 'k:行', 'v:行く|いく', 'v:会社|かいしゃ', 'v:日曜日|にちようび'], furigana: '[日曜日|にちようび]なのに、[会社|かいしゃ]に[行|い]きました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-noni-tesuto', kind: 'sentence', level: 'N4', jp: 'たくさん勉強したのに、テストはよくなかったです。', reading: 'たくさんべんきょうしたのに、テストはよくなかったです。', en: 'Even though I studied a lot, the test didn\'t go well.', uses: ['g:noni', 'g:ta-form', 'k:勉', 'k:強', 'v:たくさん|たくさん', 'v:テスト|テスト', 'v:する|する', 'v:よい|よい'], furigana: 'たくさん[勉強|べんきょう]したのに、テストはよくなかったです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10315190', kind: 'sentence', level: 'N4', jp: 'トムとメアリーを待ってたのに、あの二人来なかったんだ。', reading: 'トムとメアリーをまってたのに、あのふたりこなかったんだ。', en: 'We waited for Tom and Mary, but they didn\'t come.', uses: ['g:noni', 'g:te-form', 'k:待', 'k:二', 'k:人', 'k:来', 'v:あの|あの', 'v:来る|くる', 'v:二人|ふたり', 'v:待つ|まつ'], furigana: 'トムとメアリーを[待|ま]ってたのに、あの[二人|ふたり][来|こ]なかったんだ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 6509118, enAuthor: 'CT', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11273472', kind: 'sentence', level: 'N4', jp: 'レモンジュースなのに、オレンジジュースみたいな味だよ。', reading: 'レモンジュースなのに、オレンジジュースみたいなあじだよ。', en: 'It\'s lemon juice, but it tastes like orange juice.', uses: ['g:noni', 'g:mitai', 'k:味', 'v:味|あじ'], furigana: 'レモンジュースなのに、オレンジジュースみたいな[味|あじ]だよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 7948578, enAuthor: 'AlanF_US', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-volitional-eiga', kind: 'sentence', level: 'N4', jp: 'あした、いっしょに映画を見に行こう。', reading: 'あした、いっしょにえいがをみにいこう。', en: 'Let\'s go and see a movie together tomorrow.', uses: ['g:volitional', 'g:ni-iku', 'k:映', 'k:画', 'k:見', 'k:行', 'v:行く|いく', 'v:映画|えいが', 'v:見る|みる', 'v:明日|あした', 'v:一緒|いっしょ'], furigana: 'あした、いっしょに[映画|えいが]を[見|み]に[行|い]こう。', chunks: { pre: 'あした、', move: ['いっしょに', '映画を', '見に', '行こう'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:124815', kind: 'sentence', level: 'N4', jp: '電車で行こう。', reading: 'でんしゃでいこう。', en: 'Let\'s take a train.', uses: ['g:volitional', 'k:電', 'k:車', 'k:行', 'v:行く|いく', 'v:電車|でんしゃ'], furigana: '[電車|でん|しゃ]で[行|い]こう。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 279178, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:188264', kind: 'sentence', level: 'N4', jp: '音楽を聞こうよ。', reading: 'おんがくをきこうよ。', en: 'Let\'s listen to some music.', uses: ['g:volitional', 'k:音', 'k:楽', 'k:聞', 'v:音楽|おんがく', 'v:聞く|きく'], furigana: '[音楽|おん|がく]を[聞|き]こうよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 25405, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11070916', kind: 'sentence', level: 'N4', jp: 'ここで待とう。', reading: 'ここでまとう。', en: 'Let\'s wait here.', uses: ['g:volitional', 'k:待', 'v:ここ|ここ', 'v:待つ|まつ'], furigana: 'ここで[待|ま]とう。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 1418699, enAuthor: 'Spamster', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:228664', kind: 'sentence', level: 'N4', jp: 'いつ行こうか。', reading: 'いついこうか。', en: 'When shall we go?', uses: ['g:volitional', 'k:行', 'v:行く|いく', 'v:いつ|いつ'], furigana: 'いつ[行|い]こうか。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 66022, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:124669', kind: 'sentence', level: 'N4', jp: '電話をかけよう。', reading: 'でんわをかけよう。', en: 'I\'ll make a phone call.', uses: ['g:volitional', 'k:電', 'k:話', 'v:かける|かける', 'v:電話|でんわ', 'v:掛ける|かける'], furigana: '[電話|でん|わ]をかけよう。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 279325, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-you-to-omou-natsu', kind: 'sentence', level: 'N4', jp: '夏休みに日本へ行こうと思っています。', reading: 'なつやすみににほんへいこうとおもっています。', en: 'I\'m thinking of going to Japan during the summer holidays.', uses: ['g:you-to-omou', 'g:volitional', 'g:to-omou', 'g:te-iru', 'g:te-form', 'k:夏', 'k:休', 'k:日', 'k:本', 'k:行', 'k:思', 'v:行く|いく', 'v:夏休み|なつやすみ', 'v:思う|おもう'], furigana: '[夏休|なつやす]みに[日本|にほん]へ[行|い]こうと[思|おも]っています。', chunks: { pre: '夏休みに', move: ['日本へ', '行こうと', '思って', 'います'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:184819', kind: 'sentence', level: 'N4', jp: '外国に行こうと思っている。', reading: 'がいこくにいこうとおもっている。', en: 'I\'m thinking of going abroad.', uses: ['g:you-to-omou', 'g:volitional', 'g:to-omou', 'g:te-iru', 'g:te-form', 'k:外', 'k:国', 'k:行', 'k:思', 'v:行く|いく', 'v:外国|がいこく', 'v:思う|おもう'], furigana: '[外国|がい|こく]に[行|い]こうと[思|おも]っている。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 21949, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:193297', kind: 'sentence', level: 'N4', jp: 'もっと運動しようと思います。', reading: 'もっとうんどうしようとおもいます。', en: 'I\'m going to get more exercise.', uses: ['g:you-to-omou', 'g:volitional', 'g:to-omou', 'k:運', 'k:動', 'k:思', 'v:もっと|もっと', 'v:思う|おもう'], furigana: 'もっと[運動|うん|どう]しようと[思|おも]います。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 30462, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11021427', kind: 'sentence', level: 'N4', jp: '今日の夕飯はカレーを作ろうと思います。', reading: 'きょうのゆうはんはカレーをつくろうとおもいます。', en: 'I think I\'ll make curry for dinner tonight.', uses: ['g:you-to-omou', 'g:volitional', 'g:to-omou', 'k:今', 'k:日', 'k:夕', 'k:飯', 'k:作', 'k:思', 'v:カレー|カレー', 'v:今日|きょう', 'v:作る|つくる', 'v:夕飯|ゆうはん', 'v:思う|おもう'], furigana: '[今日|きょう]の[夕飯|ゆう|はん]はカレーを[作|つく]ろうと[思|おも]います。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12530413, enAuthor: 'pip', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10868206', kind: 'sentence', level: 'N4', jp: '手紙を書こうと思ってるんだ。', reading: 'てがみをかこうとおもってるんだ。', en: 'I\'m going to write a letter.', uses: ['g:you-to-omou', 'g:volitional', 'g:to-omou', 'k:手', 'k:紙', 'k:書', 'k:思', 'v:書く|かく', 'v:手紙|てがみ', 'v:思う|おもう'], furigana: '[手紙|て|がみ]を[書|か]こうと[思|おも]ってるんだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 6873119, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-koto-ni-suru-benkyou', kind: 'sentence', level: 'N4', jp: 'あしたから、毎日勉強することにしました。', reading: 'あしたから、まいにちべんきょうすることにしました。', en: 'I\'ve decided to study every day from tomorrow.', uses: ['g:koto-ni-suru', 'k:毎', 'k:日', 'k:勉', 'k:強', 'v:毎日|まいにち', 'v:明日|あした', 'v:する|する'], furigana: 'あしたから、[毎日|まいにち][勉強|べんきょう]することにしました。', chunks: { pre: 'あしたから、', move: ['毎日', '勉強', 'する', 'ことにしました'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:156129', kind: 'sentence', level: 'N4', jp: '私は車を買うことにした。', reading: 'わたしはくるまをかうことにした。', en: 'I decided to buy a car.', uses: ['g:koto-ni-suru', 'k:私', 'k:車', 'k:買', 'v:買う|かう', 'v:車|くるま', 'v:私|わたし'], furigana: '[私|わたし]は[車|くるま]を[買|か]うことにした。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 258406, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11852556', kind: 'sentence', level: 'N4', jp: '行かないことにしたよ。', reading: 'いかないことにしたよ。', en: 'I\'ve decided not to go.', uses: ['g:koto-ni-suru', 'g:nai-form', 'k:行', 'v:行く|いく'], furigana: '[行|い]かないことにしたよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 2359418, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8808582', kind: 'sentence', level: 'N4', jp: '漢字を勉強することにした。', reading: 'かんじをべんきょうすることにした。', en: 'I\'ve decided to study kanji.', uses: ['g:koto-ni-suru', 'k:漢', 'k:字', 'k:勉', 'k:強', 'v:漢字|かんじ', 'v:する|する'], furigana: '[漢字|かん|じ]を[勉強|べん|きょう]することにした。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2180645, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9826890', kind: 'sentence', level: 'N4', jp: '行くことにしたよ。', reading: 'いくことにしたよ。', en: 'I\'ve decided to go.', uses: ['g:koto-ni-suru', 'k:行', 'v:行く|いく'], furigana: '[行|い]くことにしたよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2826554, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nakereba-kusuri', kind: 'sentence', level: 'N4', jp: '毎日、くすりを飲まなければなりません。', reading: 'まいにち、くすりをのまなければなりません。', en: 'I have to take medicine every day.', uses: ['g:nakereba-naranai', 'k:毎', 'k:日', 'k:飲', 'v:飲む|のむ', 'v:毎日|まいにち', 'v:薬|くすり'], furigana: '[毎日|まいにち]、くすりを[飲|の]まなければなりません。', chunks: { pre: '毎日、', move: ['くすりを', '飲まなければ', 'なり', 'ません'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:121503', kind: 'sentence', level: 'N4', jp: '買い物に行かなければならない。', reading: 'かいものにいかなければならない。', en: 'I have to go shopping.', uses: ['g:nakereba-naranai', 'k:買', 'k:物', 'k:行', 'v:行く|いく', 'v:買い物|かいもの', 'v:買う|かう', 'v:物|もの'], furigana: '[買|か]い[物|もの]に[行|い]かなければならない。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 282502, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:188838', kind: 'sentence', level: 'N4', jp: '駅まで走らなければならなかった。', reading: 'えきまではしらなければならなかった。', en: 'I had to run to the station.', uses: ['g:nakereba-naranai', 'g:made', 'k:駅', 'k:走', 'v:駅|えき', 'v:走る|はしる'], furigana: '[駅|えき]まで[走|はし]らなければならなかった。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 25984, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:80523', kind: 'sentence', level: 'N4', jp: '明日の朝は早く起きなければいけませんよ。', reading: 'あしたのあさははやくおきなければいけませんよ。', en: 'You have to wake up early tomorrow morning.', uses: ['g:nakereba-naranai', 'k:明', 'k:日', 'k:朝', 'k:早', 'k:起', 'v:朝|あさ', 'v:明日|あした', 'v:起きる|おきる', 'v:早い|はやい'], furigana: '[明日|あした]の[朝|あさ]は[早|はや]く[起|お]きなければいけませんよ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 323194, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:5185663', kind: 'sentence', level: 'N4', jp: '待たなければいけない。', reading: 'またなければいけない。', en: 'You have to wait.', uses: ['g:nakereba-naranai', 'k:待', 'v:待つ|まつ'], furigana: '[待|ま]たなければいけない。', author: 'aoi0913', license: 'CC BY 2.0 FR', enId: 2549190, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nakute-mo-ii-namae', kind: 'sentence', level: 'N4', jp: '名前は書かなくてもいいです。', reading: 'なまえはかかなくてもいいです。', en: 'You don\'t have to write your name.', uses: ['g:nakute-mo-ii', 'k:名', 'k:前', 'k:書', 'v:いい|いい', 'v:書く|かく', 'v:名前|なまえ'], furigana: '[名前|なまえ]は[書|か]かなくてもいいです。', chunks: { pre: '', move: ['名前は', '書かなくても', 'いい', 'です'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:8732421', kind: 'sentence', level: 'N4', jp: '行かなくてもいいよ。', reading: 'いかなくてもいいよ。', en: 'You don\'t need to go.', uses: ['g:nakute-mo-ii', 'k:行', 'v:いい|いい', 'v:行く|いく'], furigana: '[行|い]かなくてもいいよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 69444, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:3023061', kind: 'sentence', level: 'N4', jp: '明日は来なくてもいいですよ。', reading: 'あしたはこなくてもいいですよ。', en: 'You don\'t have to come tomorrow.', uses: ['g:nakute-mo-ii', 'k:明', 'k:日', 'k:来', 'v:明日|あした', 'v:いい|いい', 'v:来る|くる'], furigana: '[明日|あした]は[来|こ]なくてもいいですよ。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 5997, enAuthor: 'Zifre', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:182548', kind: 'sentence', level: 'N4', jp: '急がなくてもいいよ。', reading: 'いそがなくてもいいよ。', en: 'You can take your time.', uses: ['g:nakute-mo-ii', 'k:急', 'v:いい|いい', 'v:急ぐ|いそぐ'], furigana: '[急|いそ]がなくてもいいよ。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 19693, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10124146', kind: 'sentence', level: 'N4', jp: 'トムは今日は仕事に行かなくてもいい。', reading: 'トムはきょうはしごとにいかなくてもいい。', en: 'Tom doesn\'t have to go to work today.', uses: ['g:nakute-mo-ii', 'k:今', 'k:日', 'k:仕', 'k:事', 'k:行', 'v:いい|いい', 'v:行く|いく', 'v:今日|きょう', 'v:仕事|しごと'], furigana: 'トムは[今日|きょう]は[仕事|し|ごと]に[行|い]かなくてもいい。', author: 'Ninja', license: 'CC BY 2.0 FR', enId: 4663981, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nai-de-asagohan', kind: 'sentence', level: 'N4', jp: 'けさは朝ごはんを食べないで学校へ行きました。', reading: 'けさはあさごはんをたべないでがっこうへいきました。', en: 'This morning I went to school without eating breakfast.', uses: ['g:nai-de', 'g:nai-form', 'k:朝', 'k:食', 'k:学', 'k:校', 'k:行', 'v:朝|あさ', 'v:行く|いく', 'v:学校|がっこう', 'v:食べる|たべる', 'v:今朝|けさ', 'v:御飯|ごはん'], furigana: 'けさは[朝|あさ]ごはんを[食|た]べないで[学校|がっこう]へ[行|い]きました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-nai-de-kasa', kind: 'sentence', level: 'N4', jp: 'きのうはかさを持たないで出かけました。', reading: 'きのうはかさをもたないででかけました。', en: 'Yesterday I went out without an umbrella.', uses: ['g:nai-de', 'g:nai-form', 'k:持', 'k:出', 'v:昨日|きのう', 'v:出かける|でかける', 'v:出る|でる', 'v:持つ|もつ', 'v:傘|かさ'], furigana: 'きのうはかさを[持|も]たないで[出|で]かけました。', chunks: { pre: '', move: ['きのうは', 'かさを', '持たないで', '出かけました'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:156631', kind: 'sentence', level: 'N4', jp: '私は仕事に行かないで一日中家にいた。', reading: 'わたしはしごとにいかないでいちにちじゅういえにいた。', en: 'I stayed home all day instead of going to work.', uses: ['g:nai-de', 'g:nai-form', 'k:私', 'k:仕', 'k:事', 'k:行', 'k:一', 'k:日', 'k:中', 'k:家', 'v:行く|いく', 'v:一日|いちにち', 'v:仕事|しごと', 'v:私|わたし'], furigana: '[私|わたし]は[仕事|し|ごと]に[行|い]かないで[一日中|いち|にち|じゅう][家|いえ]にいた。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 257903, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9993257', kind: 'sentence', level: 'N4', jp: '学校行かないで、家でゲームしたらダメ？', reading: 'がっこういかないで、いえでゲームしたらダメ？', en: 'Can\'t I just stay home and play video games instead of going to school?', uses: ['g:nai-de', 'g:nai-form', 'g:tara', 'k:学', 'k:校', 'k:行', 'k:家', 'v:家|いえ', 'v:行く|いく', 'v:学校|がっこう'], furigana: '[学校|がっ|こう][行|い]かないで、[家|いえ]でゲームしたらダメ？', author: 'Sim5634', license: 'CC BY 2.0 FR', enId: 9993292, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-nasai-te', kind: 'sentence', level: 'N4', jp: 'ごはんの前に、手をあらいなさい。', reading: 'ごはんのまえに、てをあらいなさい。', en: 'Wash your hands before you eat.', uses: ['g:nasai', 'g:mae-ni', 'k:前', 'k:手', 'v:手|て', 'v:前|まえ', 'v:御飯|ごはん', 'v:洗う|あらう'], furigana: 'ごはんの[前|まえ]に、[手|て]をあらいなさい。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:182972', kind: 'sentence', level: 'N4', jp: '起きなさい！', reading: 'おきなさい！', en: 'Get up!', uses: ['g:nasai', 'k:起', 'v:起きる|おきる'], furigana: '[起|お]きなさい！', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 20093, enAuthor: 'Dreamk33', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:83322', kind: 'sentence', level: 'N4', jp: '勉強しなさい。', reading: 'べんきょうしなさい。', en: 'Study!', uses: ['g:nasai', 'k:勉', 'k:強'], furigana: '[勉強|べん|きょう]しなさい。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 320395, enAuthor: 'shekitten', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:79943', kind: 'sentence', level: 'N4', jp: '目を開けなさい。', reading: 'めをあけなさい。', en: 'Open your eyes.', uses: ['g:nasai', 'k:目', 'k:開', 'v:開く|あく', 'v:開ける|あける', 'v:目|め'], furigana: '[目|め]を[開|あ]けなさい。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 323768, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:192757', kind: 'sentence', level: 'N4', jp: 'よく聞きなさい。', reading: 'よくききなさい。', en: 'Listen carefully.', uses: ['g:nasai', 'k:聞', 'v:聞く|きく', 'v:よく|よく'], furigana: 'よく[聞|き]きなさい。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 29922, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-imperative-sign', kind: 'sentence', level: 'N4', jp: '「止まれ」と書いてあります。', reading: '「とまれ」とかいてあります。', en: 'It says "STOP".', uses: ['g:imperative', 'g:te-aru', 'g:te-form', 'k:止', 'k:書', 'v:書く|かく', 'v:止まる|とまる'], furigana: '「[止|と]まれ」と[書|か]いてあります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-imperative-ganbare', kind: 'sentence', level: 'N4', jp: 'がんばれ！もう少しだ！', reading: 'がんばれ！もうすこしだ！', en: 'Come on! You\'re almost there!', uses: ['g:imperative', 'k:少', 'v:少し|すこし', 'v:もう|もう', 'v:頑張る|がんばる'], furigana: 'がんばれ！もう[少|すこ]しだ！', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:4443360', kind: 'sentence', level: 'N4', jp: '止まれ！', reading: 'とまれ！', en: 'Stop!', uses: ['g:imperative', 'k:止', 'v:止まる|とまる'], furigana: '[止|と]まれ！', author: 'chihiro', license: 'CC BY 2.0 FR', enId: 448320, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:140535', kind: 'sentence', level: 'N4', jp: '早く来い。', reading: 'はやくこい。', en: 'Come quick!', uses: ['g:imperative', 'k:早', 'k:来', 'v:来る|くる', 'v:早い|はやい'], furigana: '[早|はや]く[来|こ]い。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 274037, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:184886', kind: 'sentence', level: 'N4', jp: '外に出ろ。', reading: 'そとにでろ。', en: 'Get out.', uses: ['g:imperative', 'k:外', 'k:出', 'v:外|そと', 'v:出る|でる'], furigana: '[外|そと]に[出|で]ろ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 22016, enAuthor: 'Eldad', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:195365', kind: 'sentence', level: 'N4', jp: 'まっすぐ行け。', reading: 'まっすぐいけ。', en: 'Go straight on.', uses: ['g:imperative', 'k:行', 'v:行く|いく', 'v:まっすぐ|まっすぐ'], furigana: 'まっすぐ[行|い]け。', author: 'Take32', license: 'CC BY 2.0 FR', enId: 32539, enAuthor: 'Dejo', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-na-sign', kind: 'sentence', level: 'N4', jp: '「ここに入るな」と書いてありますよ。', reading: '「ここにはいるな」とかいてありますよ。', en: 'It says "Keep out".', uses: ['g:na-prohibitive', 'g:te-aru', 'g:te-form', 'k:入', 'k:書', 'v:書く|かく', 'v:ここ|ここ', 'v:入る|はいる'], furigana: '「ここに[入|はい]るな」と[書|か]いてありますよ。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:224594', kind: 'sentence', level: 'N4', jp: 'ここでは走るな。', reading: 'ここでははしるな。', en: 'Don\'t run here.', uses: ['g:na-prohibitive', 'k:走', 'v:ここ|ここ', 'v:走る|はしる'], furigana: 'ここでは[走|はし]るな。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 61929, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:5072721', kind: 'sentence', level: 'N4', jp: '食べるな！', reading: 'たべるな！', en: 'Don\'t eat!', uses: ['g:na-prohibitive', 'k:食', 'v:食べる|たべる'], furigana: '[食|た]べるな！', author: '999yudai', license: 'CC BY 2.0 FR', enId: 5072694, enAuthor: 'CarpeLanam', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:164115', kind: 'sentence', level: 'N4', jp: '私のペンを使うな。', reading: 'わたしのペンをつかうな。', en: 'Don\'t use my pen.', uses: ['g:na-prohibitive', 'k:私', 'k:使', 'v:使う|つかう', 'v:私|わたし', 'v:ペン|ペン'], furigana: '[私|わたし]のペンを[使|つか]うな。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 250395, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10903600', kind: 'sentence', level: 'N4', jp: 'ここには来るな。', reading: 'ここにはくるな。', en: 'Don\'t come here.', uses: ['g:na-prohibitive', 'k:来', 'v:来る|くる', 'v:ここ|ここ'], furigana: 'ここには[来|く]るな。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 5247785, enAuthor: 'CarpeLanam', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-hitsuyou-nihongo', kind: 'sentence', level: 'N4', jp: 'この仕事には日本語がひつようです。', reading: 'このしごとにはにほんごがひつようです。', en: 'This job requires Japanese.', uses: ['g:hitsuyou', 'k:仕', 'k:事', 'k:日', 'k:本', 'k:語', 'v:この|この', 'v:仕事|しごと', 'v:必要|ひつよう'], furigana: 'この[仕事|しごと]には[日本語|にほんご]がひつようです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-hitsuyou-pasupooto', kind: 'sentence', level: 'N4', jp: 'パスポートがひつようですか。', reading: 'パスポートがひつようですか。', en: 'Do I need a passport?', uses: ['g:hitsuyou', 'v:必要|ひつよう'], furigana: 'パスポートがひつようですか。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-hitsuyou-kaku', kind: 'sentence', level: 'N4', jp: 'もう一度書くひつようがあります。', reading: 'もういちどかくひつようがあります。', en: 'You need to write it again.', uses: ['g:hitsuyou', 'g:ga-arimasu', 'k:一', 'k:度', 'k:書', 'v:書く|かく', 'v:もう一度|もういちど', 'v:一度|いちど', 'v:もう|もう', 'v:必要|ひつよう'], furigana: 'もう[一度|いちど][書|か]くひつようがあります。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-hitsuyou-hayaku', kind: 'sentence', level: 'N4', jp: 'あしたは早く来るひつようはありません。', reading: 'あしたははやくくるひつようはありません。', en: 'There\'s no need to come early tomorrow.', uses: ['g:hitsuyou', 'k:早', 'k:来', 'v:来る|くる', 'v:早い|はやい', 'v:明日|あした', 'v:必要|ひつよう'], furigana: 'あしたは[早|はや]く[来|く]るひつようはありません。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-ku-ni-suru-heya', kind: 'sentence', level: 'N4', jp: 'へやをきれいにしてください。', reading: 'へやをきれいにしてください。', en: 'Please tidy up the room.', uses: ['g:ku-ni-suru', 'g:te-kudasai', 'g:te-form', 'v:きれい|きれい', 'v:ください|ください', 'v:部屋|へや'], furigana: 'へやをきれいにしてください。', chunks: { pre: '', move: ['へやを', 'きれいに', 'して', 'ください'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:194079', kind: 'sentence', level: 'N4', jp: 'もう少し大きくして。', reading: 'もうすこしおおきくして。', en: 'A little louder.', uses: ['g:ku-ni-suru', 'g:te-form', 'k:少', 'k:大', 'v:大きい|おおきい', 'v:少し|すこし', 'v:もう|もう'], furigana: 'もう[少|すこ]し[大|おお]きくして。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 31248, enAuthor: 'engberg', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:202004', kind: 'sentence', level: 'N4', jp: 'テレビの音大きくして。', reading: 'テレビのおとおおきくして。', en: 'Turn up the TV.', uses: ['g:ku-ni-suru', 'g:te-form', 'k:音', 'k:大', 'v:大きい|おおきい', 'v:テレビ|テレビ'], furigana: 'テレビの[音|おと][大|おお]きくして。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 39214, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-ku-ni-suru-oto', kind: 'sentence', level: 'N4', jp: 'テレビの音を小さくしなさい。', reading: 'テレビのおとをちいさくしなさい。', en: 'Turn the TV down.', uses: ['g:ku-ni-suru', 'g:nasai', 'k:音', 'k:小', 'v:音|おと', 'v:小さい|ちいさい', 'v:テレビ|テレビ'], furigana: 'テレビの[音|おと]を[小|ちい]さくしなさい。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-amari-mise', kind: 'sentence', level: 'N4', jp: 'この店はあまり高くないです。', reading: 'このみせはあまりたかくないです。', en: 'This shop isn\'t very expensive.', uses: ['g:amari-nai', 'k:店', 'k:高', 'v:あまり|あまり', 'v:この|この', 'v:高い|たかい', 'v:店|みせ'], furigana: 'この[店|みせ]はあまり[高|たか]くないです。', chunks: { pre: 'この', move: ['店は', 'あまり', '高く', 'ない'], post: 'です。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-zenzen-hon', kind: 'sentence', level: 'N4', jp: 'その本はぜんぜんおもしろくなかったです。', reading: 'そのほんはぜんぜんおもしろくなかったです。', en: 'That book wasn\'t interesting at all.', uses: ['g:amari-nai', 'k:本', 'v:おもしろい|おもしろい', 'v:その|その', 'v:本|ほん', 'v:全然|ぜんぜん', 'v:面白い|おもしろい'], furigana: 'その[本|ほん]はぜんぜんおもしろくなかったです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:12957013', kind: 'sentence', level: 'N4', jp: 'テレビはあまり見ない。', reading: 'テレビはあまりみない。', en: 'I don\'t watch TV often.', uses: ['g:amari-nai', 'k:見', 'v:あまり|あまり', 'v:テレビ|テレビ', 'v:見る|みる'], furigana: 'テレビはあまり[見|み]ない。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 12712866, enAuthor: 'rul', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:230324', kind: 'sentence', level: 'N4', jp: 'あまり時間がないんだ。', reading: 'あまりじかんがないんだ。', en: 'I don\'t have much time.', uses: ['g:amari-nai', 'k:時', 'k:間', 'v:あまり|あまり', 'v:時間|じかん', 'v:ない|ない'], furigana: 'あまり[時間|じ|かん]がないんだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 67690, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9695689', kind: 'sentence', level: 'N4', jp: '新聞はあまり読まないよ。', reading: 'しんぶんはあまりよまないよ。', en: 'I don\'t really read newspapers.', uses: ['g:amari-nai', 'k:新', 'k:聞', 'k:読', 'v:あまり|あまり', 'v:新聞|しんぶん', 'v:読む|よむ'], furigana: '[新聞|しん|ぶん]はあまり[読|よ]まないよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 1230773, enAuthor: 'alec', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-sonna-ni-tesuto', kind: 'sentence', level: 'N4', jp: 'このテストはそんなにむずかしくなかったです。', reading: 'このテストはそんなにむずかしくなかったです。', en: 'This test wasn\'t that hard.', uses: ['g:sonna-ni', 'v:この|この', 'v:テスト|テスト', 'v:そんなに|そんなに', 'v:難しい|むずかしい'], furigana: 'このテストはそんなにむずかしくなかったです。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:12312123', kind: 'sentence', level: 'N4', jp: 'どうしてそんなに高いの？', reading: 'どうしてそんなにたかいの？', en: 'Why does it cost so much?', uses: ['g:sonna-ni', 'g:doushite', 'k:高', 'v:高い|たかい', 'v:どうして|どうして', 'v:そんなに|そんなに'], furigana: 'どうしてそんなに[高|たか]いの？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10741557, enAuthor: 'ddnktr', enLicense: 'CC0 1.0', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:4855', kind: 'sentence', level: 'N4', jp: 'そんなに待ちたくない。', reading: 'そんなにまちたくない。', en: 'I don\'t want to wait that long.', uses: ['g:sonna-ni', 'k:待', 'v:待つ|まつ', 'v:そんなに|そんなに'], furigana: 'そんなに[待|ま]ちたくない。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1438, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11741527', kind: 'sentence', level: 'N4', jp: 'なんでこんなに安いの？', reading: 'なんでこんなにやすいの？', en: 'Why\'s it so cheap?', uses: ['g:sonna-ni', 'k:安', 'v:こんな|こんな', 'v:安い|やすい'], furigana: 'なんでこんなに[安|やす]いの？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10288157, enAuthor: 'ddnktr', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-passive-ashi', kind: 'sentence', level: 'N4', jp: '電車の中で、足をふまれました。', reading: 'でんしゃのなかで、あしをふまれました。', en: 'Someone stepped on my foot on the train.', uses: ['g:passive', 'k:電', 'k:車', 'k:中', 'k:足', 'v:足|あし', 'v:電車|でんしゃ', 'v:中|なか', 'v:踏む|ふむ'], furigana: '[電車|でんしゃ]の[中|なか]で、[足|あし]をふまれました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-passive-nikki', kind: 'sentence', level: 'N4', jp: '母ににっきを読まれました。', reading: 'ははににっきをよまれました。', en: 'My mother read my diary (and I was upset).', uses: ['g:passive', 'k:母', 'k:読', 'v:読む|よむ', 'v:母|はは', 'v:日記|にっき'], furigana: '[母|はは]ににっきを[読|よ]まれました。', chunks: { pre: '', move: ['母に', 'にっきを', '読まれ', 'ました'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:13569023', kind: 'sentence', level: 'N4', jp: 'トムに同じことを聞かれた。', reading: 'トムにおなじことをきかれた。', en: 'Tom asked me the same thing.', uses: ['g:passive', 'k:同', 'k:聞', 'v:同じ|おなじ', 'v:聞く|きく', 'v:事|こと'], furigana: 'トムに[同|おな]じことを[聞|き]かれた。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2543413, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:12018756', kind: 'sentence', level: 'N4', jp: 'もっと水を飲んだ方がいいと先生に言われたよ。', reading: 'もっとみずをのんだほうがいいとせんせいにいわれたよ。', en: 'My doctor told me that I should drink more water.', uses: ['g:passive', 'g:ta-form', 'k:水', 'k:飲', 'k:方', 'k:先', 'k:生', 'k:言', 'v:いい|いい', 'v:言う|いう', 'v:先生|せんせい', 'v:飲む|のむ', 'v:水|みず', 'v:もっと|もっと'], furigana: 'もっと[水|みず]を[飲|の]んだ[方|ほう]がいいと[先生|せん|せい]に[言|い]われたよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 4385837, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-causative-souji', kind: 'sentence', level: 'N4', jp: '母は弟にへやをそうじさせました。', reading: 'はははおとうとにへやをそうじさせました。', en: 'My mother made my younger brother clean the room.', uses: ['g:causative', 'k:母', 'k:弟', 'v:弟|おとうと', 'v:母|はは', 'v:部屋|へや', 'v:掃除|そうじ'], furigana: '[母|はは]は[弟|おとうと]にへやをそうじさせました。', chunks: { pre: '母は', move: ['弟に', 'へやを', 'そうじ', 'させました'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-causative-yomu', kind: 'sentence', level: 'N4', jp: '先生は学生に本を読ませました。', reading: 'せんせいはがくせいにほんをよませました。', en: 'The teacher had the students read the book.', uses: ['g:causative', 'k:先', 'k:生', 'k:学', 'k:本', 'k:読', 'v:学生|がくせい', 'v:先生|せんせい', 'v:本|ほん', 'v:読む|よむ'], furigana: '[先生|せんせい]は[学生|がくせい]に[本|ほん]を[読|よ]ませました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:138033', kind: 'sentence', level: 'N4', jp: 'トムをすぐに行かせます。', reading: 'トムをすぐにいかせます。', en: 'I\'ll have Tom go right away.', uses: ['g:causative', 'k:行', 'v:行く|いく', 'v:すぐに|すぐに'], furigana: 'トムをすぐに[行|い]かせます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 275202, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:146817', kind: 'sentence', level: 'N4', jp: '少し休ませてください。', reading: 'すこしやすませてください。', en: 'Please let me take a short break.', uses: ['g:causative', 'g:te-kudasai', 'g:te-form', 'k:少', 'k:休', 'v:ください|ください', 'v:少し|すこし', 'v:休む|やすむ'], furigana: '[少|すこ]し[休|やす]ませてください。', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 10548216, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:8726978', kind: 'sentence', level: 'N4', jp: 'トムに運転させるつもり？', reading: 'トムにうんてんさせるつもり？', en: 'Are you going to let Tom drive?', uses: ['g:causative', 'k:運', 'k:転', 'v:つもり|つもり', 'v:運転|うんてん'], furigana: 'トムに[運転|うん|てん]させるつもり？', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 6438422, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:2105551', kind: 'sentence', level: 'N4', jp: '家に帰らせてください。', reading: 'いえにかえらせてください。', en: 'Please let me go home.', uses: ['g:causative', 'g:te-kudasai', 'g:te-form', 'k:家', 'k:帰', 'v:家|いえ', 'v:帰る|かえる', 'v:ください|ください'], furigana: '[家|いえ]に[帰|かえ]らせてください。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1433780, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-causative-passive-piano', kind: 'sentence', level: 'N4', jp: '子どものとき、母にピアノをれんしゅうさせられました。', reading: 'こどものとき、ははにピアノをれんしゅうさせられました。', en: 'When I was a child, my mother made me practise the piano.', uses: ['g:causative-passive', 'g:causative', 'g:passive', 'k:子', 'k:母', 'v:母|はは', 'v:子|こ', 'v:ピアノ|ピアノ', 'v:時|とき', 'v:練習|れんしゅう'], furigana: '[子|こ]どものとき、[母|はは]にピアノをれんしゅうさせられました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-causative-passive-shachou', kind: 'sentence', level: 'N4', jp: '社長に日曜日もはたらかされました。', reading: 'しゃちょうににちようびもはたらかされました。', en: 'The boss made me work on Sunday too.', uses: ['g:causative-passive', 'g:causative', 'g:passive', 'k:社', 'k:長', 'k:日', 'k:曜', 'v:日曜日|にちようび', 'v:働く|はたらく'], furigana: '[社長|しゃちょう]に[日曜日|にちようび]もはたらかされました。', chunks: { pre: '', move: ['社長に', '日曜日も', 'はたらか', 'されました'], post: '。', star: [2, 3] }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:155026', kind: 'sentence', level: 'N4', jp: '私は長い間待たされた。', reading: 'わたしはながいあいだまたされた。', en: 'I was made to wait for a long time.', uses: ['g:causative-passive', 'g:causative', 'g:passive', 'k:私', 'k:長', 'k:間', 'k:待', 'v:長い|ながい', 'v:待つ|まつ', 'v:私|わたし'], furigana: '[私|わたし]は[長|なが]い[間|あいだ][待|ま]たされた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 259513, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11846442', kind: 'sentence', level: 'N4', jp: 'トムに食べさせられたんだ。', reading: 'トムにたべさせられたんだ。', en: 'Tom made me eat it.', uses: ['g:causative-passive', 'g:causative', 'g:passive', 'k:食', 'v:食べる|たべる'], furigana: 'トムに[食|た]べさせられたんだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 3674163, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:225374', kind: 'sentence', level: 'N4', jp: 'ケイトはその本を読まされた。', reading: 'ケイトはそのほんをよまされた。', en: 'Kate was made to read the book.', uses: ['g:causative-passive', 'g:causative', 'g:passive', 'k:本', 'k:読', 'v:その|その', 'v:本|ほん', 'v:読む|よむ'], furigana: 'ケイトはその[本|ほん]を[読|よ]まされた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 62711, enAuthor: 'CP', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-shika-saifu', kind: 'sentence', level: 'N4', jp: 'さいふに百円しかありません。', reading: 'さいふにひゃくえんしかありません。', en: 'I only have 100 yen in my wallet.', uses: ['g:shika-nai', 'k:百', 'k:円', 'v:財布|さいふ', 'v:円|えん'], furigana: 'さいふに[百円|ひゃくえん]しかありません。', chunks: { pre: 'さいふに', move: ['百円', 'しか', 'あり', 'ません'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:11102012', kind: 'sentence', level: 'N4', jp: '店にはこれしかありません。', reading: 'みせにはこれしかありません。', en: 'It\'s the only one there is in the shop.', uses: ['g:shika-nai', 'k:店', 'v:これ|これ', 'v:店|みせ'], furigana: '[店|みせ]にはこれしかありません。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 42211, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:12882301', kind: 'sentence', level: 'N4', jp: '女の子しかいなかった。', reading: 'おんなのこしかいなかった。', en: 'There were only girls.', uses: ['g:shika-nai', 'k:女', 'k:子', 'v:女|おんな', 'v:女の子|おんなのこ', 'v:子|こ'], furigana: '[女|おんな]の[子|こ]しかいなかった。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9855534, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:155443', kind: 'sentence', level: 'N4', jp: '千円しか持ってません。', reading: 'せんえんしかもってません。', en: 'I have no more than one thousand yen.', uses: ['g:shika-nai', 'k:千', 'k:円', 'k:持', 'v:持つ|もつ', 'v:円|えん'], furigana: '[千|せん][円|えん]しか[持|も]ってません。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 259095, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9748980', kind: 'sentence', level: 'N4', jp: 'フランス語しか知らないの。', reading: 'フランスごしかしらないの。', en: 'French is the only language I know.', uses: ['g:shika-nai', 'k:語', 'k:知', 'v:知る|しる', 'v:語|ご'], furigana: 'フランス[語|ご]しか[知|し]らないの。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 5909947, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-number-mo-neru', kind: 'sentence', level: 'N4', jp: 'きのうは十時間もねました。', reading: 'きのうはじゅうじかんもねました。', en: 'Yesterday I slept for ten whole hours.', uses: ['g:number-mo', 'k:十', 'k:時', 'k:間', 'v:昨日|きのう', 'v:時間|じかん', 'v:寝る|ねる'], furigana: 'きのうは[十時間|じゅうじかん]もねました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-number-mo-party', kind: 'sentence', level: 'N4', jp: 'パーティーに人が五十人も来ました。', reading: 'パーティーにひとがごじゅうにんもきました。', en: 'As many as fifty people came to the party.', uses: ['g:number-mo', 'k:人', 'k:五', 'k:十', 'k:来', 'v:パーティー|パーティー', 'v:人|ひと', 'v:人|にん', 'v:来る|くる'], furigana: 'パーティーに[人|ひと]が[五十|ご|じゅう][人|にん]も[来|き]ました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-number-mo-eki', kind: 'sentence', level: 'N4', jp: '駅で一時間も待ちました。', reading: 'えきでいちじかんもまちました。', en: 'I waited at the station for a whole hour.', uses: ['g:number-mo', 'k:駅', 'k:一', 'k:時', 'k:間', 'k:待', 'v:駅|えき', 'v:時間|じかん', 'v:待つ|まつ'], furigana: '[駅|えき]で[一|いち][時間|じ|かん]も[待|ま]ちました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-number-mo-hon', kind: 'sentence', level: 'N4', jp: 'この本は三千円もしました。', reading: 'このほんはさんぜんえんもしました。', en: 'This book cost as much as 3,000 yen.', uses: ['g:number-mo', 'k:本', 'k:三', 'k:千', 'k:円', 'v:この|この', 'v:本|ほん', 'v:円|えん', 'v:する|する'], furigana: 'この[本|ほん]は[三千|さん|ぜん][円|えん]もしました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:2113607', kind: 'sentence', level: 'N4', jp: 'トムは何時間も雨の中立っていた。', reading: 'トムはなんじかんもあめのなかたっていた。', en: 'Tom had been standing in the rain for what seemed like hours.', uses: ['g:number-mo', 'g:te-ita', 'g:te-form', 'k:何', 'k:時', 'k:間', 'k:雨', 'k:中', 'k:立', 'v:雨|あめ', 'v:時間|じかん', 'v:立つ|たつ'], furigana: 'トムは[何|なん][時間|じ|かん]も[雨|あめ]の[中|なか][立|た]っていた。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1040626, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-to-iwarete-asagohan', kind: 'sentence', level: 'N4', jp: '朝ごはんを食べるのは体にいいと言われています。', reading: 'あさごはんをたべるのはからだにいいといわれています。', en: 'Eating breakfast is said to be good for you.', uses: ['g:to-iwarete-iru', 'g:passive', 'g:te-iru', 'g:te-form', 'k:朝', 'k:食', 'k:体', 'k:言', 'v:朝|あさ', 'v:いい|いい', 'v:言う|いう', 'v:体|からだ', 'v:食べる|たべる', 'v:御飯|ごはん'], furigana: '[朝|あさ]ごはんを[食|た]べるのは[体|からだ]にいいと[言|い]われています。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-to-iwarete-tatemono', kind: 'sentence', level: 'N4', jp: 'この建物は百年前に建てられたと言われています。', reading: 'このたてものはひゃくねんまえにたてられたといわれています。', en: 'This building is said to have been built a hundred years ago.', uses: ['g:to-iwarete-iru', 'g:passive', 'g:te-iru', 'g:te-form', 'k:建', 'k:物', 'k:百', 'k:年', 'k:前', 'k:言', 'v:言う|いう', 'v:この|この', 'v:建物|たてもの', 'v:建てる|たてる', 'v:年|ねん'], furigana: 'この[建物|たてもの]は[百年|ひゃくねん][前|まえ]に[建|た]てられたと[言|い]われています。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-to-iwarete-raamen', kind: 'sentence', level: 'N4', jp: 'この店のラーメンは町でいちばんおいしいと言われています。', reading: 'このみせのラーメンはまちでいちばんおいしいといわれています。', en: 'This shop\'s ramen is said to be the best in town.', uses: ['g:to-iwarete-iru', 'g:passive', 'g:te-iru', 'g:te-form', 'k:店', 'k:町', 'k:言', 'v:言う|いう', 'v:いちばん|いちばん', 'v:おいしい|おいしい', 'v:この|この', 'v:町|まち', 'v:店|みせ'], furigana: 'この[店|みせ]のラーメンは[町|まち]でいちばんおいしいと[言|い]われています。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-sonkeigo-kyoushitsu', kind: 'sentence', level: 'N4', jp: '先生は今、教室にいらっしゃいます。', reading: 'せんせいはいま、きょうしつにいらっしゃいます。', en: 'The teacher is in the classroom now.', uses: ['g:sonkeigo-verbs', 'k:先', 'k:生', 'k:今', 'k:教', 'k:室', 'v:今|いま', 'v:教室|きょうしつ', 'v:先生|せんせい', 'v:いらっしゃる|いらっしゃる'], furigana: '[先生|せんせい]は[今|いま]、[教室|きょうしつ]にいらっしゃいます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-sonkeigo-meshiagaru', kind: 'sentence', level: 'N4', jp: 'どうぞ、めしあがってください。', reading: 'どうぞ、めしあがってください。', en: 'Please, go ahead and eat.', uses: ['g:sonkeigo-verbs', 'g:te-kudasai', 'g:te-form', 'v:ください|ください', 'v:どうぞ|どうぞ', 'v:召し上がる|めしあがる'], furigana: 'どうぞ、めしあがってください。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:4805143', kind: 'sentence', level: 'N4', jp: 'お子さんはいらっしゃいますか？', reading: 'おこさんはいらっしゃいますか？', en: 'Do you have children?', uses: ['g:sonkeigo-verbs', 'k:子', 'v:いらっしゃる|いらっしゃる', 'v:子|こ', 'v:お子さん|おこさん'], furigana: 'お[子|こ]さんはいらっしゃいますか？', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 434570, enAuthor: 'lukaszpp', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:226566', kind: 'sentence', level: 'N4', jp: 'お名前は何とおっしゃいますか。', reading: 'おなまえはなんとおっしゃいますか。', en: 'May I ask your name?', uses: ['g:sonkeigo-verbs', 'k:名', 'k:前', 'k:何', 'v:名前|なまえ', 'v:何|なん', 'v:おっしゃる|おっしゃる'], furigana: 'お[名前|な|まえ]は[何|なん]とおっしゃいますか。', author: 'tommy__san', license: 'CC BY 2.0 FR', enId: 347327, enAuthor: 'sysko', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:202257', kind: 'sentence', level: 'N4', jp: 'デザートは何になさいますか？', reading: 'デザートはなんになさいますか？', en: 'What would you like for dessert?', uses: ['g:sonkeigo-verbs', 'k:何', 'v:何|なん', 'v:なさる|なさる'], furigana: 'デザートは[何|なん]になさいますか？', author: 'tommy_san', license: 'CC BY 2.0 FR', enId: 39470, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:228622', kind: 'sentence', level: 'N4', jp: 'いつ日本にいらっしゃったんですか。', reading: 'いつにほんにいらっしゃったんですか。', en: 'When did you come to Japan?', uses: ['g:sonkeigo-verbs', 'k:日', 'k:本', 'v:いつ|いつ', 'v:いらっしゃる|いらっしゃる'], furigana: 'いつ[日本|に|ほん]にいらっしゃったんですか。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 16755, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-o-ni-naru-kaeri', kind: 'sentence', level: 'N4', jp: '先生はもうお帰りになりました。', reading: 'せんせいはもうおかえりになりました。', en: 'The teacher has already gone home.', uses: ['g:o-ni-naru', 'g:mou', 'k:先', 'k:生', 'k:帰', 'v:帰る|かえる', 'v:先生|せんせい', 'v:もう|もう', 'v:なる|なる'], furigana: '[先生|せんせい]はもうお[帰|かえ]りになりました。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:4913', kind: 'sentence', level: 'N4', jp: '何かお飲みになりますか？', reading: 'なにかおのみになりますか？', en: 'Would you like something to drink?', uses: ['g:o-ni-naru', 'k:何', 'k:飲', 'v:何|なに', 'v:飲む|のむ', 'v:なる|なる'], furigana: '[何|なに]かお[飲|の]みになりますか？', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1504, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:198421', kind: 'sentence', level: 'N4', jp: 'バーでお待ちになりますか。', reading: 'バーでおまちになりますか。', en: 'Would you like to wait in the bar?', uses: ['g:o-ni-naru', 'k:待', 'v:待つ|まつ', 'v:なる|なる'], furigana: 'バーでお[待|ま]ちになりますか。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 35612, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:3357887', kind: 'sentence', level: 'N4', jp: '私のをお使いになりますか？', reading: 'わたしのをおつかいになりますか？', en: 'Do you want to use mine?', uses: ['g:o-ni-naru', 'k:私', 'k:使', 'v:使う|つかう', 'v:私|わたし', 'v:なる|なる'], furigana: '[私|わたし]のをお[使|つか]いになりますか？', author: 'arnab', license: 'CC BY 2.0 FR', enId: 1461962, enAuthor: 'Spamster', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9546334', kind: 'sentence', level: 'N4', jp: '「よくある質問」はお読みになりましたか？', reading: '「よくあるしつもん」はおよみになりましたか？', en: 'Have you read the FAQ?', uses: ['g:o-ni-naru', 'k:質', 'k:問', 'k:読', 'v:質問|しつもん', 'v:よく|よく', 'v:読む|よむ', 'v:なる|なる'], furigana: '「よくある[質問|しつ|もん]」はお[読|よ]みになりましたか？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 1635952, enAuthor: 'Spamster', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-o-kudasai-suwari', kind: 'sentence', level: 'N4', jp: 'どうぞ、こちらにおすわりください。', reading: 'どうぞ、こちらにおすわりください。', en: 'Please have a seat here.', uses: ['g:o-kudasai', 'v:ください|ください', 'v:こちら|こちら', 'v:どうぞ|どうぞ', 'v:座る|すわる'], furigana: 'どうぞ、こちらにおすわりください。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-o-kudasai-kochira', kind: 'sentence', level: 'N4', jp: 'こちらで少しお待ちください。', reading: 'こちらですこしおまちください。', en: 'Please wait here a moment.', uses: ['g:o-kudasai', 'k:少', 'k:待', 'v:こちら|こちら', 'v:少し|すこし', 'v:待つ|まつ', 'v:ください|ください'], furigana: 'こちらで[少|すこ]しお[待|ま]ちください。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10282137', kind: 'sentence', level: 'N4', jp: 'お名前をお書きください。', reading: 'おなまえをおかきください。', en: 'Please write down your name.', uses: ['g:o-kudasai', 'k:名', 'k:前', 'k:書', 'v:書く|かく', 'v:ください|ください', 'v:名前|なまえ'], furigana: 'お[名前|な|まえ]をお[書|か]きください。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 70355, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:223201', kind: 'sentence', level: 'N4', jp: 'このペンをお使いください。', reading: 'このペンをおつかいください。', en: 'Here\'s a pen for you to use.', uses: ['g:o-kudasai', 'k:使', 'v:ください|ください', 'v:この|この', 'v:使う|つかう', 'v:ペン|ペン'], furigana: 'このペンをお[使|つか]いください。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 60533, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:228854', kind: 'sentence', level: 'N4', jp: 'いつでもお電話ください。', reading: 'いつでもおでんわください。', en: 'Call me anytime.', uses: ['g:o-kudasai', 'k:電', 'k:話', 'v:いつ|いつ', 'v:ください|ください', 'v:電話|でんわ'], furigana: 'いつでもお[電話|でん|わ]ください。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 66212, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-o-suru-kaesu', kind: 'sentence', level: 'N4', jp: 'その本は、あしたおかえしします。', reading: 'そのほんは、あしたおかえしします。', en: 'I\'ll return that book to you tomorrow.', uses: ['g:o-suru', 'k:本', 'v:その|その', 'v:本|ほん', 'v:明日|あした', 'v:返す|かえす'], furigana: 'その[本|ほん]は、あしたおかえしします。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:226244', kind: 'sentence', level: 'N4', jp: 'かばんをお持ちしましょうか。', reading: 'かばんをおもちしましょうか。', en: 'Shall I carry your bag for you?', uses: ['g:o-suru', 'k:持', 'v:かばん|かばん', 'v:持つ|もつ'], furigana: 'かばんをお[持|も]ちしましょうか。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 63584, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10612520', kind: 'sentence', level: 'N4', jp: 'それは、後でお答えします。', reading: 'それは、あとでおこたえします。', en: 'I\'ll answer that later.', uses: ['g:o-suru', 'g:ato-de', 'k:後', 'k:答', 'v:後|あと', 'v:答える|こたえる', 'v:それ|それ'], furigana: 'それは、[後|あと]でお[答|こた]えします。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10608795, enAuthor: 'shekitten', enLicense: 'CC0 1.0', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:174354', kind: 'sentence', level: 'N4', jp: '後でこちらからお電話します。', reading: 'あとでこちらからおでんわします。', en: 'I\'ll call you back later.', uses: ['g:o-suru', 'g:ato-de', 'k:後', 'k:電', 'k:話', 'v:後|あと', 'v:こちら|こちら', 'v:電話|でんわ'], furigana: '[後|あと]でこちらからお[電話|でん|わ]します。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 35772, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10838340', kind: 'sentence', level: 'N4', jp: 'メールをお送りしました。', reading: 'メールをおおくりしました。', en: 'I sent you an e-mail.', uses: ['g:o-suru', 'k:送', 'v:送る|おくる'], furigana: 'メールをお[送|おく]りしました。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 1431949, enAuthor: 'CM', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-itasu-moushimasu', kind: 'sentence', level: 'N4', jp: 'はじめまして。田中ともうします。', reading: 'はじめまして。たなかともうします。', en: 'How do you do? My name is Tanaka.', uses: ['g:itasu', 'k:田', 'k:中', 'v:申す|もうす'], furigana: 'はじめまして。[田中|たなか]ともうします。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:10982402', kind: 'sentence', level: 'N4', jp: 'お知らせいたします。', reading: 'おしらせいたします。', en: 'I will inform you.', uses: ['g:itasu', 'k:知', 'v:知らせる|しらせる', 'v:致す|いたす'], furigana: 'お[知|し]らせいたします。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 13662949, enAuthor: 'terrywallwork', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:174355', kind: 'sentence', level: 'N4', jp: '後でお電話いたします。', reading: 'あとでおでんわいたします。', en: 'I will telephone you later on.', uses: ['g:itasu', 'g:ato-de', 'k:後', 'k:電', 'k:話', 'v:後|あと', 'v:電話|でんわ', 'v:致す|いたす'], furigana: '[後|あと]でお[電話|でん|わ]いたします。', author: 'Ianagisacos', license: 'CC BY 2.0 FR', enId: 240114, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:214978', kind: 'sentence', level: 'N4', jp: 'すぐそちらへまいります。', reading: 'すぐそちらへまいります。', en: 'I\'ll be with you in a second.', uses: ['g:itasu', 'v:そちら|そちら', 'v:参る|まいる'], furigana: 'すぐそちらへまいります。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 52274, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:80604', kind: 'sentence', level: 'N4', jp: '明日そちらへ持ってまいります。', reading: 'あしたそちらへもってまいります。', en: 'I\'ll bring it to you tomorrow.', uses: ['g:itasu', 'g:te-form', 'k:明', 'k:日', 'k:持', 'v:明日|あした', 'v:そちら|そちら', 'v:持つ|もつ', 'v:参る|まいる'], furigana: '[明日|あした]そちらへ[持|も]ってまいります。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 323113, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-gozaimasu-toire', kind: 'sentence', level: 'N4', jp: 'トイレは二かいにございます。', reading: 'トイレはにかいにございます。', en: 'The toilets are on the second floor.', uses: ['g:gozaimasu', 'k:二', 'v:トイレ|トイレ', 'v:二|に', 'v:ございます|ございます', 'v:階|かい'], furigana: 'トイレは[二|に]かいにございます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-gozaimasu-erebeetaa', kind: 'sentence', level: 'N4', jp: 'エレベーターはあちらでございます。', reading: 'エレベーターはあちらでございます。', en: 'The elevator is over there.', uses: ['g:gozaimasu', 'v:あちら|あちら', 'v:エレベーター|エレベーター', 'v:ございます|ございます'], furigana: 'エレベーターはあちらでございます。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:214063', kind: 'sentence', level: 'N4', jp: 'セーフティーボックスがございます。', reading: 'セーフティーボックスがございます。', en: 'We have safety deposit boxes.', uses: ['g:gozaimasu', 'v:ございます|ございます'], furigana: 'セーフティーボックスがございます。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 51354, enAuthor: 'Zifre', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:229205', kind: 'sentence', level: 'N4', jp: 'いくつかこの土地のワインもございます。', reading: 'いくつかこのとちのワインもございます。', en: 'We have some local wine.', uses: ['g:gozaimasu', 'k:土', 'k:地', 'v:いくつ|いくつ', 'v:この|この', 'v:ございます|ございます'], furigana: 'いくつかこの[土地|と|ち]のワインもございます。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 66563, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:1336459', kind: 'sentence', level: 'N4', jp: 'こちらはサービスでございます。', reading: 'こちらはサービスでございます。', en: 'It\'s on the house.', uses: ['g:gozaimasu', 'v:こちら|こちら', 'v:ございます|ございます'], furigana: 'こちらはサービスでございます。', author: 'Scott', license: 'CC BY 2.0 FR', enId: 1112522, enAuthor: 'Scott', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-ja-nai-ka-itta', kind: 'sentence', level: 'N4', jp: 'だから言ったじゃないですか。', reading: 'だからいったじゃないですか。', en: 'See, I told you so!', uses: ['g:ja-nai-ka', 'g:ta-form', 'k:言', 'v:言う|いう', 'v:だから|だから'], furigana: 'だから[言|い]ったじゃないですか。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-ja-nai-ka-kanji', kind: 'sentence', level: 'N4', jp: 'この漢字、きのう習ったじゃないか。', reading: 'このかんじ、きのうならったじゃないか。', en: 'Come on, we learned this kanji yesterday!', uses: ['g:ja-nai-ka', 'k:漢', 'k:字', 'k:習', 'v:この|この', 'v:漢字|かんじ', 'v:昨日|きのう', 'v:習う|ならう'], furigana: 'この[漢字|かん|じ]、きのう[習|なら]ったじゃないか。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:4717937', kind: 'sentence', level: 'N4', jp: 'ごめんって言ったじゃん。', reading: 'ごめんっていったじゃん。', en: 'I said sorry, didn\'t I?', uses: ['g:ja-nai-ka', 'g:tte', 'k:言', 'v:言う|いう'], furigana: 'ごめんって[言|い]ったじゃん。', author: 'riumutu', license: 'CC BY 2.0 FR', enId: 5107376, enAuthor: 'r3cca', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9112549', kind: 'sentence', level: 'N4', jp: '早いじゃん。', reading: 'はやいじゃん。', en: 'You are early.', uses: ['g:ja-nai-ka', 'k:早', 'v:早い|はやい'], furigana: '[早|はや]いじゃん。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 273992, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:3507456', kind: 'sentence', level: 'N4', jp: 'さあ飲もうじゃないか。', reading: 'さあのもうじゃないか。', en: 'Let\'s drink.', uses: ['g:ja-nai-ka', 'g:volitional', 'k:飲', 'v:飲む|のむ', 'v:もう|もう'], furigana: 'さあ[飲|の]もうじゃないか。', author: 'arnab', license: 'CC BY 2.0 FR', enId: 2111621, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-kana-ame', kind: 'sentence', level: 'N4', jp: 'あした、雨がふるかな。', reading: 'あした、あめがふるかな。', en: 'I wonder if it\'ll rain tomorrow.', uses: ['g:kana-kashira', 'k:雨', 'v:雨|あめ', 'v:明日|あした', 'v:降る|ふる'], furigana: 'あした、[雨|あめ]がふるかな。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:9854115', kind: 'sentence', level: 'N4', jp: 'あの人元気かな？', reading: 'あのひとげんきかな？', en: 'I wonder if that person is OK.', uses: ['g:kana-kashira', 'k:人', 'k:元', 'k:気', 'v:あの|あの', 'v:元気|げんき'], furigana: 'あの[人|ひと][元気|げん|き]かな？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9855387, enAuthor: 'DJ_Saidez', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10528638', kind: 'sentence', level: 'N4', jp: 'トムはあした来るかな。', reading: 'トムはあしたくるかな。', en: 'I wonder if Tom will come tomorrow.', uses: ['g:kana-kashira', 'k:来', 'v:来る|くる', 'v:明日|あした'], furigana: 'トムはあした[来|く]るかな。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 2984279, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:11162294', kind: 'sentence', level: 'N4', jp: '明日は天気かしら。', reading: 'あしたはてんきかしら。', en: 'I wonder if it\'ll be fine tomorrow.', uses: ['g:kana-kashira', 'k:明', 'k:日', 'k:天', 'k:気', 'v:明日|あした', 'v:天気|てんき'], furigana: '[明日|あした]は[天気|てん|き]かしら。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10292498, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:229506', kind: 'sentence', level: 'N4', jp: 'アンはいつ来るのかしら？', reading: 'アンはいつくるのかしら？', en: 'I wonder when Anne will come.', uses: ['g:kana-kashira', 'k:来', 'v:いつ|いつ', 'v:来る|くる'], furigana: 'アンはいつ[来|く]るのかしら？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 66866, enAuthor: 'CN', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-ka-dou-ka-ame', kind: 'sentence', level: 'N4', jp: 'あした雨がふるかどうか、わかりません。', reading: 'あしたあめがふるかどうか、わかりません。', en: 'I don\'t know whether it will rain tomorrow.', uses: ['g:ka-dou-ka', 'k:雨', 'v:雨|あめ', 'v:明日|あした', 'v:降る|ふる', 'v:分かる|わかる'], furigana: 'あした[雨|あめ]がふるかどうか、わかりません。', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:own:n4-ka-dou-ka-sensei', kind: 'sentence', level: 'N4', jp: '先生が来るかどうか聞いてください。', reading: 'せんせいがくるかどうかきいてください。', en: 'Please ask whether the teacher is coming.', uses: ['g:ka-dou-ka', 'g:te-kudasai', 'g:te-form', 'k:先', 'k:生', 'k:来', 'k:聞', 'v:聞く|きく', 'v:ください|ください', 'v:来る|くる', 'v:先生|せんせい'], furigana: '[先生|せんせい]が[来|く]るかどうか[聞|き]いてください。', chunks: { pre: '先生が', move: ['来るか', 'どうか', '聞いて', 'ください'], post: '。' }, author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:215673', kind: 'sentence', level: 'N4', jp: 'ジョージが来るかどうか知りません。', reading: 'ジョージがくるかどうかしりません。', en: 'I don\'t know if George is coming.', uses: ['g:ka-dou-ka', 'k:来', 'k:知', 'v:来る|くる', 'v:知る|しる'], furigana: 'ジョージが[来|く]るかどうか[知|し]りません。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 52975, enAuthor: 'CN', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:10187698', kind: 'sentence', level: 'N4', jp: '問題は、トムが来るかどうかです。', reading: 'もんだいは、トムがくるかどうかです。', en: 'The point is whether Tom will come or not.', uses: ['g:ka-dou-ka', 'k:問', 'k:題', 'k:来', 'v:来る|くる', 'v:問題|もんだい'], furigana: '[問題|もん|だい]は、トムが[来|く]るかどうかです。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 10187690, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:171171', kind: 'sentence', level: 'N4', jp: '今夜、行けるかどうかわからないんだ。', reading: 'こんや、いけるかどうかわからないんだ。', en: 'We\'re not sure we can come tonight.', uses: ['g:ka-dou-ka', 'g:potential', 'k:今', 'k:夜', 'k:行', 'v:行く|いく', 'v:今夜|こんや', 'v:分かる|わかる'], furigana: '[今夜|こん|や]、[行|い]けるかどうかわからないんだ。', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 243306, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:9964050', kind: 'sentence', level: 'N4', jp: 'トムが家にいるかどうか、見に行ってみようよ。', reading: 'トムがいえにいるかどうか、みにいってみようよ。', en: 'Why don\'t we go see if Tom is at home?', uses: ['g:ka-dou-ka', 'g:te-miru', 'g:volitional', 'g:ni-iku', 'g:te-form', 'k:家', 'k:見', 'k:行', 'v:家|いえ', 'v:見る|みる', 'v:行く|いく', 'v:居る|いる'], furigana: 'トムが[家|いえ]にいるかどうか、[見|み]に[行|い]ってみようよ。', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 9964046, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:own:n4-kai-kaeru', kind: 'sentence', level: 'N4', jp: 'もう帰るのかい？', reading: 'もうかえるのかい？', en: 'Are you going home already?', uses: ['g:kai', 'g:mou', 'k:帰', 'v:帰る|かえる', 'v:もう|もう'], furigana: 'もう[帰|かえ]るのかい？', author: 'jelly-jlpt', license: 'own', sources: ['own'], verified: false },
  { id: 's:tatoeba:213775', kind: 'sentence', level: 'N4', jp: 'そう思うかい？', reading: 'そうおもうかい？', en: 'Do you think so?', uses: ['g:kai', 'k:思', 'v:思う|おもう', 'v:そう|そう'], furigana: 'そう[思|おも]うかい？', author: 'small_snow', license: 'CC BY 2.0 FR', enId: 51063, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:194166', kind: 'sentence', level: 'N4', jp: 'もう終わったのかい。', reading: 'もうおわったのかい。', en: 'Have you finished already?', uses: ['g:kai', 'g:mou', 'k:終', 'v:終わる|おわる', 'v:もう|もう'], furigana: 'もう[終|お]わったのかい。', author: 'KK_kaku_', license: 'CC BY 2.0 FR', enId: 31336, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false },
  { id: 's:tatoeba:4970', kind: 'sentence', level: 'N4', jp: 'それらはみんな同じかい？', reading: 'それらはみんなおなじかい？', en: 'Are they all the same?', uses: ['g:kai', 'k:同', 'v:同じ|おなじ', 'v:それ|それ', 'v:みんな|みんな'], furigana: 'それらはみんな[同|おな]じかい？', author: 'bunbuku', license: 'CC BY 2.0 FR', enId: 1563, enAuthor: 'CK', enLicense: 'CC BY 2.0 FR', sources: ['tatoeba'], verified: false }
]);
